        case (value) inside
          [0:3]: begin
            case (en)
              1'b1: value <= value + 1;
              1'b0: value <= value;
            endcase
          end
          [4:7]: begin
            case (en)
              1'b1: value <= value - 1;
              1'b0: value <= value;
            endcase
          end
          [8:11]: value <= 4'b0101;
          [12:15]: value <= 0;
        endcase
      end
    endcase
  end
