                                     1'b0: hist_bin <= hist_bin;
                                     default: hist_bin <= hist_bin;
                                 endcase
                                 // Handle dec condition with range check
                                 case(dec)
                                     1'b1: begin
                                               case(hist_bin > 4'd0)
                                                   1'b1: hist_bin <= hist_bin - 1;
                                                   1'b0: hist_bin <= hist_bin;
                                                   default: hist_bin <= hist_bin;
                                               endcase
                                           end
                                     1'b0: hist_bin <= hist_bin;
                                     default: hist_bin <= hist_bin;
                                 endcase
                             end
                      [8:12]: case(dec)
                                  1'b1: hist_bin <= hist_bin - 1;
                                  1'b0: hist_bin <= hist_bin;
                                  default: hist_bin <= hist_bin;
                              endcase
                      [13:15]: hist_bin <= 4'd7;
                  endcase
        endcase
    end
