module case_saturation(input logic clk, rst, add, sub, output logic [3:0] sat_val);
    always_ff @(posedge clk or posedge rst) begin
        case(rst)
            1'b1: sat_val <= 4'b1000;
            1'b0: case(sat_val)
                      4'b0000: case(add)
                                   1'b1: sat_val <= 4'b0001;
                                   1'b0: sat_val <= sat_val;
                                   default: sat_val <= sat_val;
                               endcase
                      4'b1111: case(sub)
                                   1'b1: sat_val <= 4'b1110;
                                   1'b0: sat_val <= sat_val;
                                   default: sat_val <= sat_val;
                               endcase
                      default: begin
                                   // Handle add condition with saturation check
                                   case(add)
                                       1'b1: begin
                                                 case(sat_val != 4'b1111)
                                                     1'b1: sat_val <= sat_val + 1;
                                                     1'b0: sat_val <= sat_val;
                                                     default: sat_val <= sat_val;
                                                 endcase
                                             end
                                       1'b0: sat_val <= sat_val;
                                       default: sat_val <= sat_val;
                                   endcase
                                   // Handle sub condition with saturation check
                                   case(sub)
                                       1'b1: begin
                                                 case(sat_val != 4'b0000)
                                                     1'b1: sat_val <= sat_val - 1;
                                                     1'b0: sat_val <= sat_val;
                                                     default: sat_val <= sat_val;
                                                 endcase
                                             end
                                       1'b0: sat_val <= sat_val;
                                       default: sat_val <= sat_val;
                                   endcase
                               end
                  endcase
        endcase
    end
endmodule,"module case_saturation_assertions(input logic clk, rst, add, sub, output logic [3:0] sat_val)

