module case_bias_adj(input logic clk, rst, inc, dec, output logic [3:0] bias);
    always_ff @(posedge clk or posedge rst) begin
        case(rst)
            1'b1: bias <= 4'b1000;
            1'b0: case(bias) inside
                      [0:3]: begin
                                 // Handle inc condition
                                 case(inc)
                                     1'b1: bias <= bias + 2;
                                     1'b0: bias <= bias;
                                     default: bias <= bias;
                                 endcase
                                 // Handle dec condition with zero check
                                 case(dec)
                                     1'b1: begin
                                               case(bias == 0)
                                                   1'b1: bias <= 0;
                                                   1'b0: bias <= bias - 1;
                                                   default: bias <= bias;
                                               endcase
                                           end
                                     1'b0: bias <= bias;
                                     default: bias <= bias;
                                 endcase
                             end
                      [4:11]: begin
                                 // Handle inc condition with max check
                                 case(inc)
                                     1'b1: begin
                                               case(bias < 4'b1111)
                                                   1'b1: bias <= bias + 1;
                                                   1'b0: bias <= bias;
                                                   default: bias <= bias;
                                               endcase
                                           end
                                     1'b0: bias <= bias;
                                     default: bias <= bias;
                                 endcase
                                 // Handle dec condition with min check
                                 case(dec)
                                     1'b1: begin
                                               case(bias > 4'b0000)
                                                   1'b1: bias <= bias - 1;
                                                   1'b0: bias <= bias;
                                                   default: bias <= bias;
                                               endcase
                                           end
                                     1'b0: bias <= bias;
                                     default: bias <= bias;
                                 endcase
                             end
                      [12:15]: begin
                                 // Handle inc condition
                                 case(inc)
                                     1'b1: bias <= 4'b1111;
                                     1'b0: bias <= bias;
                                     default: bias <= bias;
                                 endcase
                                 // Handle dec condition
                                 case(dec)
                                     1'b1: bias <= bias - 2;
                                     1'b0: bias <= bias;
                                     default: bias <= bias;
                                 endcase
                             end
                  endcase
        endcase
