module traffic_light_mealy (
    input logic clk,
    input logic rst_n,
    input logic pedestrian_req,
    output logic [1:0] lights,  // 00: Green, 01: Yellow, 10: Red
    output logic walk_signal
);

typedef enum logic [1:0] {GREEN, YELLOW, RED} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    case(rst_n)
        1'b0: state <= GREEN;
        1'b1: state <= next_state;
        default: state <= GREEN;
    endcase
end

// Next state and output logic
always_comb begin
    next_state = state;
    lights = {2{1'b0}};
    walk_signal = 1'b0;

    case (state)
        GREEN: begin
            lights = 2'b00;  // Green
            case(pedestrian_req)
                1'b1: begin
                    next_state = YELLOW;
                    walk_signal = 1'b1;  // Walk signal triggered immediately
                end
                1'b0: begin
                    next_state = state;
                end
                default: begin
                    next_state = state;
                end
            endcase
        end

        YELLOW: begin
            lights = 2'b01;  // Yellow
            // Count 3 cycles then change to red
            // (simplified - normally would have counter)
            next_state = RED;
        end

        RED: begin
            lights = 2'b10;  // Red
            // After pedestrian crossing time
            next_state = GREEN;
        end
    endcase
end

endmodule,"module traffic_light_mealy_assertions(

module serial_adder_mealy (
    input logic clk,
    input logic rst_n,
    input logic a_bit,
    input logic b_bit,
    input logic valid,
    output logic sum_bit,
    output logic carry_out
);

typedef enum logic {C0, C1} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= C0;
    else
        state <= next_state;
end

// Next state and output logic
always_comb begin
    next_state = state;
    sum_bit = 1'b0;
    carry_out = 1'b0;

    if (valid) begin
        case (state)
            C0: begin  // Carry = 0
                case ({a_bit, b_bit})
                    2'b00: begin
                        sum_bit = 1'b0;
                        next_state = C0;
                    end
                    2'b01, 2'b10: begin
                        sum_bit = 1'b1;
                        next_state = C0;
                    end
                    2'b11: begin
                        sum_bit = 1'b0;
                        next_state = C1;
                    end
                endcase
            end

            C1: begin  // Carry = 1
                case ({a_bit, b_bit})
                    2'b00: begin
                        sum_bit = 1'b1;
                        next_state = C0;
                    end
                    2'b01, 2'b10: begin
                        sum_bit = 1'b0;
                        next_state = C1;
                    end
                    2'b11: begin
                        sum_bit = 1'b1;
                        next_state = C1;
                    end
                endcase
            end
        endcase

        // Final carry out
        if (state == C1 && {a_bit, b_bit} != 2'b00)
            carry_out = 1'b1;
    end
end
endmodule,"module serial_adder_mealy_assertions(

module mealy_pulse_generator (
    input  logic clk,
    input  logic rst_n,
    input  logic button,
    output logic pulse
);

    // State encoding - only 2 states needed
    typedef enum logic {
        IDLE,   // Waiting for button press
        PRESS   // Button is currently pressed
    } state_t;

    state_t current_state, next_state;

    // Sequential block: state update
    always_ff @(posedge clk or negedge rst_n) begin
        case(rst_n)
            1'b0: current_state <= IDLE;
            1'b1: current_state <= next_state;
            default: current_state <= IDLE;
        endcase
    end

    // Combinational block: next state and output logic
    always_comb begin
        next_state = current_state;  // Default to stay in current state
        pulse = 1'b0;                // Default output

        case (current_state)
            IDLE: begin
                case(button)
                    1'b1: begin
                        next_state = PRESS;
                        pulse = 1'b1;    // Mealy output: pulse immediately on press
                    end
                    1'b0: begin
                        next_state = current_state;
                    end
                    default: begin
                        next_state = current_state;
                    end
                endcase
            end

            PRESS: begin
                case(button)
                    1'b0: next_state = IDLE;  // Wait for button release
                    1'b1: next_state = current_state;
                    default: next_state = current_state;
                endcase
                // No pulse while in PRESS state
            end
        endcase
    end
endmodule,"module mealy_pulse_generator (

module mealy_vending_machine (
    input  logic clk,
    input  logic rst_n,
    input  logic nickel,      // 5 cents
    input  logic dime,        // 10 cents
    input  logic quarter,     // 25 cents
    input  logic dispense_btn,
    output logic product_out,
    output logic [1:0] change  // 00: no change, 01: nickel, 10: dime
);

    // State encoding - represents accumulated value
    typedef enum logic [2:0] {
        S0,    // $0.00
        S5,    // $0.05
        S10,   // $0.10
        S15,   // $0.15
        S20,   // $0.20
        S25,   // $0.25
        S30,   // $0.30
        S35    // $0.35
    } state_t;

    state_t current_state, next_state;

    // Product price is $0.25
    localparam PRICE = 3'b100; // 25 cents in binary

    // Sequential block: state update
    always_ff @(posedge clk or negedge rst_n) begin
        case(rst_n)
            1'b0: current_state <= S0;
            1'b1: current_state <= next_state;
            default: current_state <= S0;
        endcase
    end

    // Combinational block: next state logic using case
    always_comb begin
        next_state = current_state;

        case (current_state)
            S0: begin
                case (1'b1)
                    nickel:  next_state = S5;
                    dime:    next_state = S10;
                    quarter: next_state = S25;
                    default: next_state = current_state;
                endcase
            end

            S5: begin
                case (1'b1)
                    nickel:  next_state = S10;
                    dime:    next_state = S15;
                    quarter: next_state = S30;
                    default: next_state = current_state;
                endcase
            end

            S10: begin
                case (1'b1)
                    nickel:  next_state = S15;
                    dime:    next_state = S20;
                    quarter: next_state = S35;
                    default: next_state = current_state;
                endcase
            end

            S15: begin
                case (1'b1)
                    nickel:  next_state = S20;
                    dime:    next_state = S25;
                    quarter: next_state = S35;
                    default: next_state = current_state;
                endcase
            end

            S20: begin
                case (1'b1)
                    nickel:  next_state = S25;
                    dime:    next_state = S30;
                    quarter: next_state = S35;
                    default: next_state = current_state;
                endcase
            end

            S25: begin
                case (1'b1)
                    nickel:  next_state = S30;
                    dime:    next_state = S35;
                    quarter: next_state = S35;
                    default: next_state = current_state;
                endcase
            end

            S30: begin
                case (1'b1)
                    nickel:  next_state = S35;
                    dime:    next_state = S35;
                    quarter: next_state = S35;
                    default: next_state = current_state;
                endcase
            end

            S35: begin
                // Max value, ignore additional coins
                next_state = S35;
            end
        endcase
    end

    // Combinational block: Mealy outputs
    always_comb begin
        product_out = 1'b0;
        change = 2'b00;

        case (current_state)
            S25: begin
                case(dispense_btn)
                    1'b1: begin
                        product_out = 1'b1;  // Exact change, no refund
                    end
                    1'b0: begin
                        product_out = 1'b0;
                        change = 2'b00;
                    end
                    default: begin
                        product_out = 1'b0;
                        change = 2'b00;
                    end
                endcase
            end

            S30: begin
                case(dispense_btn)
                    1'b1: begin
                        product_out = 1'b1;
                        change = 2'b01;      // Return nickel ($0.05)
                    end
