                    1'b0: begin
                        product_out = 1'b0;
                        change = 2'b00;
                    end
                    default: begin
                        product_out = 1'b0;
                        change = 2'b00;
                    end
                endcase
            end

            default: begin
                product_out = 1'b0;
                change = 2'b00;
            end
        endcase
