module counter_2bit_mealy (
    input logic clk,
    input logic rst_n,
    input logic enable,
    output logic [1:0] count,
    output logic overflow
);

typedef enum logic [1:0] {C0, C1, C2, C3} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    case(rst_n)
        1'b0: state <= C0;
        1'b1: state <= next_state;
        default: state <= C0;
    endcase
end

// Output logic for current count
assign count = state;

// Next state and overflow detection
always_comb begin
    next_state = state;
    overflow = 1'b0;

    case(enable)
        1'b1: case(state)
                  C0: next_state = C1;
                  C1: next_state = C2;
                  C2: next_state = C3;
                  C3: begin
                      next_state = C0;
                      overflow = 1'b1;  // Overflow on transition
                  end
                  default: next_state = state;
              endcase
        1'b0: begin
                  next_state = state;
                  overflow = 1'b0;
              end
        default: begin
                     next_state = state;
                     overflow = 1'b0;
                 end
    endcase
end

endmodule,"module counter_2bit_mealy_assertions()

module parity_checker_mealy (
    input logic clk,
    input logic rst_n,
    input logic din,
    input logic valid,
    output logic error
);

typedef enum logic {EVEN, ODD} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    case(rst_n)
        1'b0: state <= EVEN;
        1'b1: state <= next_state;
        default: state <= EVEN;
    endcase
end

// Next state and output logic
always_comb begin
    next_state = state;
    error = 1'b0;

    case(valid)
        1'b1: case(state)
                  EVEN: begin
                      case(din)
                          1'b1: next_state = ODD;
                          1'b0: next_state = state;
                          default: next_state = state;
                      endcase
                      // Error detection on final valid
                      error = 1'b0;  // Even parity with even bits is OK
                  end

                  ODD: begin
                      case(din)
                          1'b0: next_state = EVEN;
                          1'b1: next_state = state;
                          default: next_state = state;
                      endcase
                      // Error detection on final valid
                      error = 1'b1;  // Odd parity with odd bits is error
                  end

                  default: begin
                      next_state = state;
                      error = 1'b0;
                  end
              endcase
        1'b0: begin
                  next_state = state;
                  error = 1'b0;
              end
        default: begin
                     next_state = state;
                     error = 1'b0;
                 end
    endcase
end

endmodule,"module parity_checker_mealy_assertions(input logic clk, input logic rst_n, input logic din, input logic valid, output logic error)

module sequence_detector_101 (
    input  logic clk,
    input  logic rst_n,
    input  logic din,
    output logic dout
);

    // State encoding
    typedef enum logic [1:0] {
        S0 = 2'b00,  // No bits matched
        S1 = 2'b01,  // Matched '1'
        S2 = 2'b10   // Matched '10'
    } state_t;

    state_t current_state, next_state;

    // Sequential logic (using only case statements)
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: current_state <= S0;
            1'b1: current_state <= next_state;
        endcase
    end

    // Combinational logic (Mealy)
    always_comb begin
        // Default assignments
        next_state = current_state;
        dout = 1'b0;

        case (current_state)
            S0: begin
                case (din)
                    1'b1: next_state = S1;
                    1'b0: next_state = S0;
                endcase
            end

            S1: begin
                case (din)
                    1'b1: next_state = S1;
                    1'b0: next_state = S2;
                endcase
            end

            S2: begin
                case (din)
                    1'b1: begin
                        next_state = S1;
                        dout = 1'b1;  // Mealy output: detected 101
                    end
                    1'b0: next_state = S0;
                endcase
            end
        endcase
    end
