module pattern_detector_1101 (
    input logic clk,
    input logic rst_n,
    input logic din,
    output logic match
);

typedef enum logic [2:0] {S0, S1, S11, S110} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    case (rst_n)
        1'b0: state <= S0;
        1'b1: state <= next_state;
    endcase
end

// Next state and output logic
always_comb begin
    next_state = state;
    match = 1'b0;

    case (state)
        S0: begin
            case (din)
                1'b1: next_state = S1;
                1'b0: next_state = S0;
            endcase
        end

        S1: begin
            case (din)
                1'b1: next_state = S11;
                1'b0: next_state = S0;
            endcase
        end

        S11: begin
            case (din)
                1'b1: next_state = S11;  // Overlap case
                1'b0: next_state = S110;
            endcase
        end

        S110: begin
            case (din)
                1'b1: begin
                    next_state = S1;      // Last '1' can start new sequence
                    match = 1'b1;         // Pattern 1101 detected
                end
                1'b0: next_state = S0;
            endcase
        end
    endcase
end
