// OBI Protocol Controller - Case-Statements-Only Implementation
// Implements a simplified OBI master interface with request/response handling
// No if/else statements, no loops - only case statements and combinational/sequential blocks

module obi_protocol_controller (
    // Clock and reset
    input  logic clk,
    input  logic rst_n,

    // OBI Master Interface (to interconnect)
    output logic        obi_cmd_valid,
    input  logic        obi_cmd_ready,
    output logic [31:0] obi_cmd_addr,
    output logic [2:0]  obi_cmd_opc,    // 000: read, 001: write, 010: atomic
    output logic [31:0] obi_cmd_wdata,
    output logic [3:0]  obi_cmd_be,

    input  logic        obi_rsp_valid,
    output logic        obi_rsp_ready,
    input  logic [31:0] obi_rsp_rdata,
    input  logic [2:0]  obi_rsp_err,    // 000: ok, 001: decode error, 010: slave error

    // Local control interface
    input  logic        req_valid,
    output logic        req_ready,
    input  logic [31:0] req_addr,
    input  logic [2:0]  req_opc,
    input  logic [31:0] req_wdata,
    input  logic [3:0]  req_be,

    output logic        rsp_valid,
    input  logic        rsp_ready,
    output logic [31:0] rsp_rdata,
    output logic [2:0]  rsp_err,

    // Status outputs
    output logic [2:0]  state_out,
    output logic        pending_transaction
);

    // State encoding
    typedef enum logic [2:0] {
        IDLE         = 3'b000,
        WAIT_CMD_ACK = 3'b001,
        WAIT_RSP     = 3'b010,
        WAIT_RSP_ACK = 3'b011,
        ERROR_RECOV  = 3'b100
    } state_t;

    state_t current_state, next_state;

    // Transaction storage registers
    logic [31:0] stored_addr;
    logic [2:0]  stored_opc;
    logic [31:0] stored_wdata;
    logic [3:0]  stored_be;

    // Response storage
    logic [31:0] stored_rdata;
    logic [2:0]  stored_err;

    // Counter for error recovery (3-cycle timeout)
    logic [1:0] error_counter;

    // -----------------------------------------------------------------
    // BLOCK 1: Sequential State Register (Clock/Reset)
    // -----------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                current_state <= IDLE;
                error_counter <= 2'b00;
            end
            1'b1: begin
                current_state <= next_state;
                case (current_state)
                    ERROR_RECOV: begin
                        // Increment counter during error recovery
                        case (error_counter)
                            2'b11: error_counter <= 2'b11;
                            default: error_counter <= error_counter + 2'b01;
                        endcase
                    end
                    default: begin
                        error_counter <= 2'b00;
                    end
                endcase
            end
        endcase
    end

    // -----------------------------------------------------------------
    // BLOCK 2: Next State Logic (Combinational)
    // -----------------------------------------------------------------
    always_comb begin
        next_state = current_state;

        case (current_state)
            IDLE: begin
                case (req_valid)
                    1'b1: next_state = WAIT_CMD_ACK;
                    1'b0: next_state = IDLE;
                endcase
            end

            WAIT_CMD_ACK: begin
                case (obi_cmd_ready)
                    1'b1: begin
                        case (obi_cmd_opc)
                            3'b010: begin  // Atomic operation requires response
                                next_state = WAIT_RSP;
                            end
                            default: begin  // Read/Write operations
                                case (obi_cmd_opc)
                                    3'b000: next_state = WAIT_RSP;  // Read needs response
                                    3'b001: next_state = WAIT_RSP_ACK; // Write needs response
                                    default: next_state = WAIT_RSP;
                                endcase
                            end
                        endcase
                    end
                    1'b0: next_state = WAIT_CMD_ACK;
                endcase
            end

            WAIT_RSP: begin
                case (obi_rsp_valid)
                    1'b1: begin
                        case (rsp_ready)
                            1'b1: next_state = IDLE;
                            1'b0: next_state = WAIT_RSP_ACK;
                        endcase
                    end
                    1'b0: next_state = WAIT_RSP;
                endcase
            end

            WAIT_RSP_ACK: begin
                case (rsp_ready)
                    1'b1: begin
                        case (obi_rsp_err)
                            3'b000: next_state = IDLE;
                            default: next_state = ERROR_RECOV;
                        endcase
                    end
                    1'b0: next_state = WAIT_RSP_ACK;
                endcase
            end

            ERROR_RECOV: begin
                case (error_counter)
                    2'b11: next_state = IDLE;
                    default: next_state = ERROR_RECOV;
                endcase
            end

            default: next_state = IDLE;
        endcase
    end

    // -----------------------------------------------------------------
    // BLOCK 3: Transaction Capture & OBI Command Generation (Combinational)
    // -----------------------------------------------------------------
    always_comb begin
        // Default assignments
        obi_cmd_valid = 1'b0;
        obi_cmd_addr = 32'b0;
        obi_cmd_opc = 3'b000;
        obi_cmd_wdata = 32'b0;
        obi_cmd_be = 4'b0000;
        req_ready = 1'b0;

        case (current_state)
            IDLE: begin
                case (req_valid)
                    1'b1: begin
                        req_ready = 1'b1;
                        obi_cmd_valid = 1'b1;
                        obi_cmd_addr = req_addr;
                        obi_cmd_opc = req_opc;
                        obi_cmd_wdata = req_wdata;
                        obi_cmd_be = req_be;
                    end
                    default: begin
                        req_ready = 1'b0;
                    end
                endcase
            end

            WAIT_CMD_ACK: begin
                // Keep driving same command until accepted
                obi_cmd_valid = 1'b1;
                obi_cmd_addr = stored_addr;
                obi_cmd_opc = stored_opc;
                obi_cmd_wdata = stored_wdata;
                obi_cmd_be = stored_be;
                req_ready = 1'b0;
            end

            default: begin
                obi_cmd_valid = 1'b0;
                req_ready = 1'b0;
            end
        endcase
    end

    // -----------------------------------------------------------------
    // BLOCK 4: Transaction Storage Registers (Sequential)
    // -----------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                stored_addr <= 32'b0;
                stored_opc <= 3'b000;
                stored_wdata <= 32'b0;
                stored_be <= 4'b0000;
            end
            1'b1: begin
                case (current_state)
                    IDLE: begin
                        case (req_valid & req_ready)
                            1'b1: begin
                                stored_addr <= req_addr;
                                stored_opc <= req_opc;
                                stored_wdata <= req_wdata;
                                stored_be <= req_be;
                            end
                            default: begin
                                stored_addr <= stored_addr;
                                stored_opc <= stored_opc;
                                stored_wdata <= stored_wdata;
                                stored_be <= stored_be;
                            end
                        endcase
                    end
                    default: begin
                        stored_addr <= stored_addr;
                        stored_opc <= stored_opc;
                        stored_wdata <= stored_wdata;
                        stored_be <= stored_be;
                    end
                endcase
            end
        endcase
    end

    // -----------------------------------------------------------------
    // BLOCK 5: Response Capture & OBI Response Handshake (Combinational)
    // -----------------------------------------------------------------
    always_comb begin
        // Default assignments
        obi_rsp_ready = 1'b0;
        rsp_valid = 1'b0;
        rsp_rdata = 32'b0;
        rsp_err = 3'b000;

        case (current_state)
            WAIT_RSP: begin
                case (obi_rsp_valid)
                    1'b1: begin
                        obi_rsp_ready = 1'b1;
                        rsp_valid = 1'b1;
                        rsp_rdata = obi_rsp_rdata;
                        rsp_err = obi_rsp_err;
                    end
                    default: begin
                        obi_rsp_ready = 1'b0;
                        rsp_valid = 1'b0;
                    end
                endcase
            end

            WAIT_RSP_ACK: begin
                // Keep response valid until consumed
                obi_rsp_ready = 1'b0;
                rsp_valid = 1'b1;
                rsp_rdata = stored_rdata;
                rsp_err = stored_err;
            end

            default: begin
                obi_rsp_ready = 1'b0;
                rsp_valid = 1'b0;
            end
        endcase
    end

    // -----------------------------------------------------------------
    // BLOCK 6: Response Storage Registers (Sequential)
    // -----------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                stored_rdata <= 32'b0;
                stored_err <= 3'b000;
            end
            1'b1: begin
                case (current_state)
                    WAIT_RSP: begin
                        case (obi_rsp_valid)
                            1'b1: begin
                                stored_rdata <= obi_rsp_rdata;
                                stored_err <= obi_rsp_err;
                            end
                            default: begin
                                stored_rdata <= stored_rdata;
                                stored_err <= stored_err;
                            end
                        endcase
                    end
                    default: begin
                        stored_rdata <= stored_rdata;
                        stored_err <= stored_err;
                    end
                endcase
            end
        endcase
    end

    // -----------------------------------------------------------------
    // BLOCK 7: Status Outputs (Combinational)
    // -----------------------------------------------------------------
    always_comb begin
        state_out = current_state;

        case (current_state)
            IDLE: begin
                pending_transaction = 1'b0;
            end
            default: begin
                pending_transaction = 1'b1;
            end
        endcase
    end

endmodule,"module obi_protocol_controller_assertions(

module pwm_generator_mealy (
    input logic clk,
    input logic rst_n,
    input logic [7:0] period,
    input logic [7:0] duty_cycle,
    input logic update_duty,
    output logic pwm_out
);

typedef enum logic [1:0] {HIGH, LOW, UPDATE} state_t;
state_t state, next_state;
logic [7:0] counter, next_counter;
logic [7:0] current_duty, next_current_duty;

// Sequential logic
always_ff @(posedge clk or negedge rst_n) begin
    case (rst_n)
        1'b0: begin
            state <= LOW;
            counter <= 8'b0;
            current_duty <= 8'b0;
        end
        1'b1: begin
            state <= next_state;
            counter <= next_counter;
            current_duty <= next_current_duty;
        end
    endcase
end

// Combinational logic
always_comb begin
    // Default assignments
    next_state = state;
    next_counter = counter;
    next_current_duty = current_duty;
    pwm_out = 1'b0;

    // Counter increment (always increments unless reset)
    next_counter = counter + 1;

    // Duty cycle update
    case (update_duty)
        1'b1: next_current_duty = duty_cycle;
        default: next_current_duty = current_duty;
    endcase

    case (state)
        HIGH: begin
            pwm_out = 1'b1;

            // Check for end of high period
            case (counter == (current_duty - 1))
                1'b1: begin
                    next_state = LOW;
                    pwm_out = 1'b0;  // Mealy: immediate transition
                end
            endcase

            // Mealy: immediate duty cycle update during HIGH state
            case (update_duty && (counter < duty_cycle))
                1'b1: pwm_out = 1'b1;
            endcase
        end

        LOW: begin
            pwm_out = 1'b0;

            // Check for end of low period
            case (counter == (period - 1))
                1'b1: begin
                    next_state = HIGH;
                    next_counter = 8'b0;
                    pwm_out = 1'b1;  // Mealy: immediate transition
                end
            endcase

            // Mealy: update request during LOW state
            case (update_duty && (duty_cycle > 0))
                1'b1: next_state = UPDATE;
            endcase
        end

        UPDATE: begin
            pwm_out = 1'b1;  // Mealy: immediate response to new duty cycle
            next_state = HIGH;
            next_counter = 8'b0;
        end
    endcase
end

endmodule,"module pwm_generator_mealy (

// Mealy FSM: Weapons System Controller
// Tracks: Safe Mode -> Armed -> Fire
// Outputs depend on both state and input (Mealy)
// All conditional logic implemented with case statements only
module weapons_system (
    input  logic clk,
    input  logic rst_n,
    input  logic arm_switch,    // 1: arm command
    input  logic trigger,       // 1: fire command
    input  logic safety_bypass, // 1: override safety
    output logic fire_enable,   // 1: weapon can fire
    output logic armed_led,     // 1: armed indicator
    output logic fault          // 1: illegal condition
);

    // State encoding
    typedef enum logic [1:0] {
        SAFE   = 2'b00,
        ARMED  = 2'b01,
        FAULT  = 2'b10
    } state_t;

    state_t curr_state, next_state;

    // --------------------------------------------------
    // Sequential block: State register (synchronous)
    // --------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: curr_state <= SAFE;
            1'b1: curr_state <= next_state;
        endcase
    end

    // --------------------------------------------------
    // Combinational block 1: Next state logic
    // All conditional logic via case statements
    // --------------------------------------------------
    always_comb begin
        next_state = curr_state;  // default: stay

        case (curr_state)
            SAFE: begin
                case ({arm_switch, safety_bypass})
                    2'b10: next_state = ARMED;   // arm without bypass
                    2'b11: next_state = FAULT;   // arm with bypass = unsafe
                    default: next_state = SAFE;
                endcase
            end
            ARMED: begin
                case ({trigger, arm_switch})
                    2'b10: next_state = SAFE;    // trigger fired
                    2'b00: next_state = SAFE;    // arm_switch turned off
                    default: next_state = ARMED;
                endcase
            end
            FAULT: begin
                next_state = FAULT;   // latch fault until reset
            end
        endcase
    end

    // --------------------------------------------------
    // Combinational block 2: Mealy + Moore outputs
    // All conditional logic via case statements
    // --------------------------------------------------
    always_comb begin
        // Defaults
        fire_enable = 1'b0;
        armed_led   = 1'b0;
        fault       = 1'b0;

        case (curr_state)
            SAFE: begin
                armed_led = 1'b0;
                // Mealy: trigger with safety_bypass causes fault
                case ({trigger, safety_bypass})
                    2'b11: fault = 1'b1;
                    default: fault = 1'b0;
                endcase
                // No fire in SAFE state
                fire_enable = 1'b0;
            end

            ARMED: begin
                armed_led = 1'b1;
                // Mealy: fire_enable active when trigger pressed
                case (trigger)
                    1'b1: fire_enable = 1'b1;
                    default: fire_enable = 1'b0;
                endcase
                // Armed LED turns off if arm_switch deasserted
                case (arm_switch)
                    1'b0: armed_led = 1'b0;
                    default: armed_led = 1'b1;
                endcase
            end

            FAULT: begin
                fault = 1'b1;
                armed_led = 1'b0;
                fire_enable = 1'b0;
            end
        endcase
    end

endmodule,"// Assertion module for weapons_system

module seq_detector_1001_nonoverlap (
    input logic clk,
    input logic rst_n,
    input logic din,
    output logic detected
);

typedef enum logic [2:0] {S0, S1, S10, S100} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    case (rst_n)
        1'b0: state <= S0;
        1'b1: state <= next_state;
    endcase
end

// Next state and output logic
always_comb begin
    next_state = state;
    detected = 1'b0;

    case (state)
        S0: begin
            case (din)
                1'b1: next_state = S1;
                1'b0: next_state = S0;
            endcase
        end

        S1: begin
            case (din)
                1'b1: next_state = S1;
                1'b0: next_state = S10;
            endcase
        end

        S10: begin
            case (din)
                1'b1: next_state = S1;
                1'b0: next_state = S100;
            endcase
        end

        S100: begin
            case (din)
                1'b1: begin
                    next_state = S1;   // Start new sequence from last '1'
                    detected = 1'b1;   // Pattern "1001" detected
                end
                1'b0: next_state = S0; // Reset if next bit is 0
            endcase
        end
    endcase
end
