module debouncer_mealy (
    input logic clk,
    input logic rst_n,
    input logic noisy_in,
    input logic [15:0] debounce_time,
    output logic debounced_out
);

typedef enum logic [1:0] {STABLE0, COUNT0, STABLE1, COUNT1} state_t;
state_t state, next_state;
logic [15:0] counter, next_counter;

// Sequential logic
always_ff @(posedge clk or negedge rst_n) begin
    case (rst_n)
        1'b0: begin
            state <= STABLE0;
            counter <= 16'b0;
        end
        1'b1: begin
            state <= next_state;
            counter <= next_counter;
        end
    endcase
end

// Combinational logic
always_comb begin
    // Default assignments
    next_state = state;
    next_counter = counter;
    debounced_out = 1'b0;

    // Counter update logic
    case (state == COUNT0 || state == COUNT1)
        1'b1: next_counter = counter + 1;
        1'b0: next_counter = 16'b0;
    endcase

    case (state)
        STABLE0: begin
            debounced_out = 1'b0;
            case (noisy_in)
                1'b1: next_state = COUNT0;
            endcase
        end

        COUNT0: begin
            debounced_out = 1'b0;

            case (!noisy_in)
                1'b1: next_state = STABLE0;  // Glitch, go back
            endcase

            case (counter == (debounce_time - 1))
                1'b1: begin
                    next_state = STABLE1;
                    debounced_out = 1'b1;  // Mealy: output high immediately
                end
            endcase
        end

        STABLE1: begin
            debounced_out = 1'b1;
            case (!noisy_in)
                1'b1: next_state = COUNT1;
            endcase
        end

        COUNT1: begin
            debounced_out = 1'b1;

            case (noisy_in)
                1'b1: next_state = STABLE1;  // Glitch, go back
            endcase

            case (counter == (debounce_time - 1))
                1'b1: begin
                    next_state = STABLE0;
                    debounced_out = 1'b0;  // Mealy: output low immediately
                end
            endcase
        end
    endcase
end

endmodule,"module debouncer_mealy_assertions(input logic clk, input logic rst_n, input logic noisy_in, input logic [15:0] debounce_time, output logic debounced_out)

// AHB-Lite Slave Controller with Burst Support
// Implements: IDLE, SETUP, ACCESS states with burst (SINGLE, INCR, WRAP4)
// No if/else statements - only case statements for all control and data paths
// Total lines: ~140

module ahb_slave_burst_ctrl (
    // Clock and Reset
    input  logic        HCLK,
    input  logic        HRESETn,

    // AHB-Lite Interface
    input  logic        HSEL,           // Slave select
    input  logic [31:0] HADDR,
    input  logic        HWRITE,
    input  logic [ 2:0] HSIZE,
    input  logic [ 2:0] HBURST,
    input  logic [ 1:0] HTRANS,
    input  logic [31:0] HWDATA,
    output logic [31:0] HRDATA,
    output logic        HREADY,         // Slave ready
    output logic [ 1:0] HRESP,          // Response (0=OKAY, 1=ERROR)

    // Internal memory interface (simulated RAM)
    input  logic [31:0] mem_read_data,
    output logic [31:0] mem_write_data,
    output logic [31:0] mem_address,
    output logic        mem_write_en,
    output logic        mem_read_en
);

    // State encoding
    typedef enum logic [1:0] {
        IDLE    = 2'b00,
        SETUP   = 2'b01,
        ACCESS  = 2'b10
    } state_t;

    state_t current_state, next_state;

    // Burst control registers
    logic [31:0] base_addr;
    logic [31:0] current_addr;
    logic [ 2:0] burst_type;
    logic [ 2:0] burst_size;
    logic [ 1:0] burst_count;
    logic [ 1:0] burst_index;
    logic        burst_active;
    logic        last_beat;
    logic        write_pending;

    // Internal signals
    logic [31:0] next_addr_calc;
    logic        addr_align_error;
    logic        hready_next;
    logic [ 1:0] hresp_next;
    logic [31:0] mem_addr_next;
    logic        mem_we_next;
    logic        mem_re_next;
    logic [31:0] mem_wdata_next;

    // -----------------------------------------------------------------
    // Block 1: Sequential State Register (case-only)
    // -----------------------------------------------------------------
    always_ff @(posedge HCLK or negedge HRESETn) begin
        case (HRESETn)
            1'b0: current_state <= IDLE;
            default: current_state <= next_state;
        endcase
    end

    // -----------------------------------------------------------------
    // Block 2: Sequential Burst Control Registers (case-only)
    // -----------------------------------------------------------------
    always_ff @(posedge HCLK or negedge HRESETn) begin
        case (HRESETn)
            1'b0: begin
                base_addr     <= 32'd0;
                current_addr  <= 32'd0;
                burst_type    <= 3'd0;
                burst_size    <= 3'd0;
                burst_count   <= 2'd0;
                burst_index   <= 2'd0;
                burst_active  <= 1'b0;
                last_beat     <= 1'b0;
                write_pending <= 1'b0;
            end
            default: begin
                case (next_state)
                    IDLE: begin
                        case ({HSEL, HTRANS[1]})
                            2'b11: begin
                                base_addr    <= HADDR;
                                current_addr <= HADDR;
                                burst_type   <= HBURST;
                                burst_size   <= HSIZE;
                                burst_index  <= 2'd0;
                                write_pending <= HWRITE;

                                // Calculate burst active and count using nested case
                                case (HBURST)
                                    3'b000: begin
                                        burst_active <= 1'b0;
                                        burst_count <= 2'd0;
                                    end
                                    3'b001, 3'b010, 3'b011: begin
                                        burst_active <= 1'b1;
                                        // Calculate burst count for WRAP4 and INCR4
                                        case (HBURST)
                                            3'b010, 3'b001, 3'b011: burst_count <= 2'd3;
                                            default: burst_count <= 2'd0;
                                        endcase
                                    end
                                    default: begin
                                        burst_active <= 1'b0;
                                        burst_count <= 2'd0;
                                    end
                                endcase
                            end
                            default: begin
                                burst_active <= 1'b0;
                                write_pending <= 1'b0;
                                // Preserve other registers
                                base_addr    <= base_addr;
                                current_addr <= current_addr;
                                burst_type   <= burst_type;
                                burst_size   <= burst_size;
                                burst_count  <= burst_count;
                                burst_index  <= burst_index;
                                last_beat    <= last_beat;
                            end
                        endcase
                    end

                    SETUP: begin
                        case (HREADY)
                            1'b1: begin
                                current_addr <= next_addr_calc;
                                case (burst_active)
                                    1'b1: begin
                                        burst_index <= burst_index + 2'd1;
                                        case (burst_index == burst_count)
                                            1'b1: last_beat <= 1'b1;
                                            default: last_beat <= 1'b0;
                                        endcase
                                    end
                                    default: last_beat <= 1'b1;
                                endcase
                                // Preserve other registers during SETUP
                                base_addr    <= base_addr;
                                burst_type   <= burst_type;
                                burst_size   <= burst_size;
                                burst_count  <= burst_count;
                                burst_active <= burst_active;
                                write_pending <= write_pending;
                            end
                            default: begin
                                // Hold all values when HREADY is low
                                base_addr    <= base_addr;
                                current_addr <= current_addr;
                                burst_type   <= burst_type;
                                burst_size   <= burst_size;
                                burst_count  <= burst_count;
                                burst_index  <= burst_index;
                                burst_active <= burst_active;
                                last_beat    <= last_beat;
                                write_pending <= write_pending;
                            end
                        endcase
                    end

                    ACCESS: begin
                        // Maintain all values during ACCESS
                        base_addr    <= base_addr;
                        current_addr <= current_addr;
                        burst_type   <= burst_type;
                        burst_size   <= burst_size;
                        burst_count  <= burst_count;
                        burst_index  <= burst_index;
                        burst_active <= burst_active;
                        last_beat    <= last_beat;
                        write_pending <= write_pending;
                    end

                    default: begin
                        // Default hold
                        base_addr    <= base_addr;
                        current_addr <= current_addr;
                        burst_type   <= burst_type;
                        burst_size   <= burst_size;
                        burst_count  <= burst_count;
                        burst_index  <= burst_index;
                        burst_active <= burst_active;
                        last_beat    <= last_beat;
                        write_pending <= write_pending;
                    end
                endcase
            end
        endcase
    end

    // -----------------------------------------------------------------
    // Block 3: Combinational Next State Logic (case-only)
    // -----------------------------------------------------------------
    always_comb begin
        next_state = current_state;

        case (current_state)
            IDLE: begin
                case ({HSEL, HTRANS[1]})
                    2'b11: next_state = SETUP;   // Valid non-IDLE transfer
                    default: next_state = IDLE;
                endcase
            end

            SETUP: begin
                case (HREADY)
                    1'b1: next_state = ACCESS;
                    default: next_state = SETUP;
                endcase
            end

            ACCESS: begin
                case ({HREADY, last_beat})
                    2'b11: next_state = IDLE;      // Done with burst
                    2'b10: next_state = SETUP;     // More beats in burst
                    default: next_state = ACCESS;
                endcase
            end
        endcase
    end

    // -----------------------------------------------------------------
    // Block 4: Combinational Output & Address Calculation (case-only)
    // -----------------------------------------------------------------
    always_comb begin
        // Default values
        hready_next     = 1'b1;
        hresp_next      = 2'b00;
        mem_addr_next   = current_addr;
        mem_we_next     = 1'b0;
        mem_re_next     = 1'b0;
        mem_wdata_next  = HWDATA;
        next_addr_calc  = current_addr;
        addr_align_error = 1'b0;

        // Address alignment check based on HSIZE
        case (burst_size)
            3'b000: addr_align_error = |current_addr[1:0];  // Byte
            3'b001: addr_align_error = current_addr[0];     // Halfword
            3'b010: addr_align_error = |current_addr[1:0];  // Word
            default: addr_align_error = 1'b0;
        endcase

        // Next address calculation based on burst type
        case (burst_type)
            3'b000: begin  // SINGLE
                next_addr_calc = current_addr + (32'd1 << burst_size);
            end

            3'b001, 3'b011: begin  // INCR4, INCR (treated as INCR4 for simplicity)
                next_addr_calc = current_addr + (32'd1 << burst_size);
            end

            3'b010: begin  // WRAP4
                case (burst_size)
                    3'b010: begin  // Word wrapping
                        case (burst_index)
                            2'd0: next_addr_calc = {current_addr[31:4], current_addr[3:0] + 4'd4};
                            2'd1: next_addr_calc = {current_addr[31:4], current_addr[3:0] + 4'd8};
                            2'd2: next_addr_calc = {current_addr[31:4], current_addr[3:0] + 4'd12};
                            default: next_addr_calc = {current_addr[31:4], 4'd0};
                        endcase
                    end
                    default: next_addr_calc = current_addr + (32'd1 << burst_size);
                endcase
            end

            default: begin
                next_addr_calc = current_addr;
            end
        endcase

        // Main output control based on state and burst conditions
        case (current_state)
            IDLE: begin
                case ({HSEL, HTRANS[1]})
                    2'b11: begin
                        hready_next = 1'b0;  // Wait state for first access
                        case (HWRITE)
                            1'b1: mem_we_next = 1'b1;
                            1'b0: mem_re_next = 1'b1;
                        endcase
                    end
                    default: begin
                        hready_next = 1'b1;
                    end
                endcase
            end

            SETUP: begin
                case (addr_align_error)
                    1'b1: begin
                        hresp_next = 2'b01;  // ERROR response
                        hready_next = 1'b1;
                    end
                    default: begin
                        case (write_pending)
                            1'b1: mem_we_next = 1'b1;
                            1'b0: mem_re_next = 1'b1;
                        endcase
                        hready_next = 1'b0;  // Stall until memory ready
                    end
                endcase
            end

            ACCESS: begin
                case (HREADY)
                    1'b1: begin
                        hready_next = 1'b1;
                        hresp_next = 2'b00;  // OKAY response
                        // Prepare for next burst beat if needed
                        case (last_beat)
                            1'b0: begin
                                case (write_pending)
                                    1'b1: mem_we_next = 1'b1;
                                    1'b0: mem_re_next = 1'b1;
                                endcase
                            end
                        endcase
                    end
                    default: begin
                        hready_next = 1'b0;
                    end
                endcase
            end
        endcase

        // Error override for misaligned access
        case (addr_align_error)
            1'b1: begin
                case (current_state)
                    SETUP: begin
                        mem_we_next = 1'b0;
                        mem_re_next = 1'b0;
                    end
                endcase
            end
        endcase
    end

    // Connect outputs
    assign HREADY   = hready_next;
    assign HRESP    = hresp_next;
    assign HRDATA   = mem_read_data;
    assign mem_address = mem_addr_next;
    assign mem_write_en = mem_we_next;
    assign mem_read_en  = mem_re_next;
    assign mem_write_data = mem_wdata_next;

endmodule,"Here is a Python program that uses the requests library to send an HTTP request and retrieve data from a URL. This example retrieves data from the GitHub API:

//------------------------------------------------------------------------------
// Multi-Port Memory Arbiter with Write Priority
//
// A memory controller that arbitrates between 4 requesters (0-3) for a
// single memory bank. Features:
// - Write operations have absolute priority over reads
// - Round-robin arbitration among writers, and among readers when no writes
// - Sequential logic for state, combinational logic for grant/selection
// - No if/else statements - only case/casez/case inside
// - No loops
//------------------------------------------------------------------------------

module memory_arbiter (
    input  logic        clk,
    input  logic        rst_n,

    // Requester 0 interface
    input  logic        req0_wr,        // Write request
    input  logic        req0_rd,        // Read request
    input  logic [31:0] req0_addr,
    input  logic [31:0] req0_wdata,
    output logic        grant0_wr,      // Write grant
    output logic        grant0_rd,      // Read grant
    output logic [31:0] resp0_rdata,

    // Requester 1 interface
    input  logic        req1_wr,
    input  logic        req1_rd,
    input  logic [31:0] req1_addr,
    input  logic [31:0] req1_wdata,
    output logic        grant1_wr,
    output logic        grant1_rd,
    output logic [31:0] resp1_rdata,

    // Requester 2 interface
    input  logic        req2_wr,
    input  logic        req2_rd,
    input  logic [31:0] req2_addr,
    input  logic [31:0] req2_wdata,
    output logic        grant2_wr,
    output logic        grant2_rd,
    output logic [31:0] resp2_rdata,

    // Requester 3 interface
    input  logic        req3_wr,
    input  logic        req3_rd,
    input  logic [31:0] req3_addr,
    input  logic [31:0] req3_wdata,
    output logic        grant3_wr,
    output logic        grant3_rd,
    output logic [31:0] resp3_rdata,

    // Memory interface (single-ported)
    output logic        mem_wr_en,
    output logic [31:0] mem_addr,
    output logic [31:0] mem_wdata,
    input  logic [31:0] mem_rdata
);

    //--------------------------------------------------------------------------
    // Internal signals
    //--------------------------------------------------------------------------
    typedef enum logic [3:0] {  // Use 4 bits for 9 states (0-8)
        STATE_IDLE    = 4'b0000,
        STATE_WRITE0  = 4'b0001,
        STATE_WRITE1  = 4'b0010,
        STATE_WRITE2  = 4'b0011,
        STATE_WRITE3  = 4'b0100,
        STATE_READ0   = 4'b0101,
        STATE_READ1   = 4'b0110,
        STATE_READ2   = 4'b0111,
        STATE_READ3   = 4'b1000
    } state_t;

    state_t curr_state, next_state;

    // Arbitration priority tracking
    logic [1:0] last_wr_served;    // Last writer served (for round-robin)
    logic [1:0] last_rd_served;    // Last reader served (for round-robin)

    // Combined request vectors
    logic [3:0] wr_req_vec;         // Write requests from all requesters
    logic [3:0] rd_req_vec;         // Read requests from all requesters

    // Selected requester ID and operation
    logic [1:0] selected_id;
    logic       selected_is_write;

    // Grant signals (combinatorial)
    logic [3:0] grant_wr_vec;
    logic [3:0] grant_rd_vec;
    logic [31:0] rdata_vec [3:0];   // Read data per requester

    //--------------------------------------------------------------------------
    // Block 1: COMBINATIONAL - Build request vectors and priority selection
    // Uses case statements to implement priority encoder with round-robin
    //--------------------------------------------------------------------------
    always_comb begin
        // Build request vectors
        wr_req_vec = {req3_wr, req2_wr, req1_wr, req0_wr};
        rd_req_vec = {req3_rd, req2_rd, req1_rd, req0_rd};

        // Default assignments
        selected_id = 2'b00;
        selected_is_write = 1'b0;

        // Priority arbitration: Write requests have absolute priority
        // Use casez to find highest priority pending write with round-robin
        casez ({wr_req_vec, last_wr_served})
            // Round-robin starting point based on last_wr_served
            6'b???1_00: begin selected_id = 2'b00; selected_is_write = 1'b1; end  // req0_wr
            6'b??1?_01: begin selected_id = 2'b01; selected_is_write = 1'b1; end  // req1_wr
            6'b?1??_10: begin selected_id = 2'b10; selected_is_write = 1'b1; end  // req2_wr
            6'b1???_11: begin selected_id = 2'b11; selected_is_write = 1'b1; end  // req3_wr
            // Wrap-around cases (if starting point has no request)
            6'b???1_11: begin selected_id = 2'b00; selected_is_write = 1'b1; end
            6'b??1?_00: begin selected_id = 2'b01; selected_is_write = 1'b1; end
            6'b?1??_01: begin selected_id = 2'b10; selected_is_write = 1'b1; end
            6'b1???_10: begin selected_id = 2'b11; selected_is_write = 1'b1; end
            default: begin
                // No writes - handle reads with round-robin
                casez ({rd_req_vec, last_rd_served})
                    6'b???1_00: begin selected_id = 2'b00; selected_is_write = 1'b0; end
                    6'b??1?_01: begin selected_id = 2'b01; selected_is_write = 1'b0; end
                    6'b?1??_10: begin selected_id = 2'b10; selected_is_write = 1'b0; end
                    6'b1???_11: begin selected_id = 2'b11; selected_is_write = 1'b0; end
                    6'b???1_11: begin selected_id = 2'b00; selected_is_write = 1'b0; end
                    6'b??1?_00: begin selected_id = 2'b01; selected_is_write = 1'b0; end
                    6'b?1??_01: begin selected_id = 2'b10; selected_is_write = 1'b0; end
                    6'b1???_10: begin selected_id = 2'b11; selected_is_write = 1'b0; end
                    default: begin
                        selected_id = 2'b00;
                        selected_is_write = 1'b0;
                    end
                endcase
            end
        endcase
    end

    //--------------------------------------------------------------------------
    // Block 2: COMBINATIONAL - Generate per-requester grant signals and data
    // Uses case statements to decode selected_id into individual grants
    //--------------------------------------------------------------------------
    always_comb begin
        // Default: all grants deasserted
        grant_wr_vec = 4'b0000;
        grant_rd_vec = 4'b0000;

        // Set read data for each requester based on memory output
        rdata_vec[0] = mem_rdata;
        rdata_vec[1] = mem_rdata;
        rdata_vec[2] = mem_rdata;
        rdata_vec[3] = mem_rdata;

        // Decode selected requester and operation type
        case ({selected_is_write, selected_id})
            {1'b1, 2'b00}: grant_wr_vec[0] = 1'b1;
            {1'b1, 2'b01}: grant_wr_vec[1] = 1'b1;
            {1'b1, 2'b10}: grant_wr_vec[2] = 1'b1;
            {1'b1, 2'b11}: grant_wr_vec[3] = 1'b1;
            {1'b0, 2'b00}: grant_rd_vec[0] = 1'b1;
            {1'b0, 2'b01}: grant_rd_vec[1] = 1'b1;
            {1'b0, 2'b10}: grant_rd_vec[2] = 1'b1;
            {1'b0, 2'b11}: grant_rd_vec[3] = 1'b1;
            default: begin
                grant_wr_vec = 4'b0000;
                grant_rd_vec = 4'b0000;
            end
        endcase

        // Memory control signals based on selected operation
        case (selected_is_write)
            1'b1: begin
                mem_wr_en = 1'b1;
                // Select write data based on requester
                case (selected_id)
                    2'b00: mem_wdata = req0_wdata;
                    2'b01: mem_wdata = req1_wdata;
                    2'b10: mem_wdata = req2_wdata;
                    2'b11: mem_wdata = req3_wdata;
                    default: mem_wdata = 32'b0;
                endcase
                // Select address based on requester
                case (selected_id)
                    2'b00: mem_addr = req0_addr;
                    2'b01: mem_addr = req1_addr;
                    2'b10: mem_addr = req2_addr;
                    2'b11: mem_addr = req3_addr;
                    default: mem_addr = 32'b0;
                endcase
            end
            1'b0: begin
                mem_wr_en = 1'b0;
                mem_wdata = 32'b0;
                // Select address based on requester
                case (selected_id)
                    2'b00: mem_addr = req0_addr;
                    2'b01: mem_addr = req1_addr;
                    2'b10: mem_addr = req2_addr;
                    2'b11: mem_addr = req3_addr;
                    default: mem_addr = 32'b0;
                endcase
            end
            default: begin
                mem_wr_en = 1'b0;
                mem_addr = 32'b0;
                mem_wdata = 32'b0;
            end
        endcase
    end

    //--------------------------------------------------------------------------
    // Block 3: COMBINATIONAL - Next state logic for FSM
    // Uses case statements to determine next state based on current state and
    // the selected operation from the arbitration logic
    //--------------------------------------------------------------------------
    always_comb begin
        next_state = curr_state;

        case (curr_state)
            STATE_IDLE: begin
                case ({selected_is_write, |wr_req_vec, |rd_req_vec})
                    3'b1_1_x: begin  // Write exists
                        case (selected_id)
                            2'b00: next_state = STATE_WRITE0;
                            2'b01: next_state = STATE_WRITE1;
                            2'b10: next_state = STATE_WRITE2;
                            2'b11: next_state = STATE_WRITE3;
                            default: next_state = STATE_IDLE;
                        endcase
                    end
                    3'b0_0_1: begin  // Only reads exist
                        case (selected_id)
                            2'b00: next_state = STATE_READ0;
                            2'b01: next_state = STATE_READ1;
                            2'b10: next_state = STATE_READ2;
                            2'b11: next_state = STATE_READ3;
                            default: next_state = STATE_IDLE;
                        endcase
                    end
                    default: next_state = STATE_IDLE;
                endcase
            end

            STATE_WRITE0: next_state = STATE_IDLE;
            STATE_WRITE1: next_state = STATE_IDLE;
            STATE_WRITE2: next_state = STATE_IDLE;
            STATE_WRITE3: next_state = STATE_IDLE;

            STATE_READ0:  next_state = STATE_IDLE;
            STATE_READ1:  next_state = STATE_IDLE;
            STATE_READ2:  next_state = STATE_IDLE;
            STATE_READ3:  next_state = STATE_IDLE;

            default: next_state = STATE_IDLE;
        endcase
    end

    //--------------------------------------------------------------------------
    // Block 4: SEQUENTIAL - State register and priority tracking
    // Updates FSM state and maintains last-served IDs for round-robin
    //--------------------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                curr_state <= STATE_IDLE;
                last_wr_served <= 2'b00;
                last_rd_served <= 2'b00;
            end
            1'b1: begin
                curr_state <= next_state;

                // Update priority tracking based on completed operation
                case (curr_state)
                    STATE_WRITE0: last_wr_served <= 2'b00;
                    STATE_WRITE1: last_wr_served <= 2'b01;
                    STATE_WRITE2: last_wr_served <= 2'b10;
                    STATE_WRITE3: last_wr_served <= 2'b11;
                    STATE_READ0:  last_rd_served <= 2'b00;
                    STATE_READ1:  last_rd_served <= 2'b01;
                    STATE_READ2:  last_rd_served <= 2'b10;
                    STATE_READ3:  last_rd_served <= 2'b11;
                    default: begin
                        // No change on idle or other states
                        last_wr_served <= last_wr_served;
                        last_rd_served <= last_rd_served;
                    end
                endcase
            end
            default: begin
                curr_state <= STATE_IDLE;
                last_wr_served <= 2'b00;
                last_rd_served <= 2'b00;
            end
        endcase
    end

    //--------------------------------------------------------------------------
    // Output assignments (connect grant vectors to module ports)
    //--------------------------------------------------------------------------
    assign grant0_wr = grant_wr_vec[0];
    assign grant1_wr = grant_wr_vec[1];
    assign grant2_wr = grant_wr_vec[2];
    assign grant3_wr = grant_wr_vec[3];

    assign grant0_rd = grant_rd_vec[0];
    assign grant1_rd = grant_rd_vec[1];
    assign grant2_rd = grant_rd_vec[2];
    assign grant3_rd = grant_rd_vec[3];

    assign resp0_rdata = rdata_vec[0];
    assign resp1_rdata = rdata_vec[1];
    assign resp2_rdata = rdata_vec[2];
    assign resp3_rdata = rdata_vec[3];

endmodule,"Here is a Python program that uses the Natural Language Toolkit (NLTK) to tokenize sentences and words. It also uses NLTK's Part-Of-Speech (POS) tagging feature to identify parts of speech for each word in the sentence.

module edge_detector_mealy (
    input logic clk,
    input logic rst_n,
    input logic din,
    output logic rising_edge
);

typedef enum logic {IDLE, HIGH} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    case (rst_n)
        1'b0: state <= IDLE;
        1'b1: state <= next_state;
    endcase
end

// Next state and output logic (Mealy)
always_comb begin
    next_state = state;
    rising_edge = 1'b0;

    case (state)
        IDLE: begin
            case (din)
                1'b1: begin
                    next_state = HIGH;
                    rising_edge = 1'b1;  // Mealy: output depends on input
                end
            endcase
        end

        HIGH: begin
            case (din)
                1'b0: next_state = IDLE;
            endcase
        end
    endcase
end

endmodule,"module edge_detector_mealy_assertions()

module axi2apb_bridge (
    input  logic        clk,
    input  logic        rst_n,

    // AXI4-Lite Slave Interface
    input  logic [31:0] s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    input  logic [31:0] s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready,

    // APB Master Interface
    output logic [31:0] m_apb_paddr,
    output logic        m_apb_psel,
    output logic        m_apb_penable,
    output logic        m_apb_pwrite,
    output logic [31:0] m_apb_pwdata,
    input  logic [31:0] m_apb_prdata,
    input  logic        m_apb_pready,
    input  logic        m_apb_pslverr
);

	// State encoding
    typedef enum logic [1:0] {
        IDLE,
        SETUP,
        ACCESS,
        RESPONSE
    } state_t;

    // Signal declarations
    state_t current_state, next_state;
    logic [31:0] addr_reg;
    logic write_reg;
    logic is_write, is_read;
    logic aw_hsk, w_hsk, ar_hsk;

    // Block 1: State Machine Sequential Logic
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: current_state <= IDLE;
            1'b1: current_state <= next_state;
        endcase
    end

    // Block 2: Address and Control Register
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                addr_reg <= 32'b0;
                write_reg <= 1'b0;
            end
            1'b1: begin
                case (current_state)
                    IDLE: begin
                        case ({s_axi_awvalid, s_axi_arvalid})
                            2'b10, 2'b11: begin
                                addr_reg <= s_axi_awaddr;
                                write_reg <= 1'b1;
                            end
                            2'b01: begin
                                addr_reg <= s_axi_araddr;
                                write_reg <= 1'b0;
                            end
                            default: begin
                                addr_reg <= addr_reg;
                                write_reg <= write_reg;
                            end
                        endcase
                    end
                    default: begin
                        addr_reg <= addr_reg;
                        write_reg <= write_reg;
                    end
                endcase
            end
        endcase
    end

    // Block 3: Combinational Logic (All case statements, no assign)
    always_comb begin
        // Default values
        next_state = current_state;
        is_write = 1'b0;
        is_read = 1'b0;
        aw_hsk = 1'b0;
        w_hsk = 1'b0;
        ar_hsk = 1'b0;

        // Calculate handshake signals using case
        case ({s_axi_awvalid, s_axi_awready})
            2'b11: aw_hsk = 1'b1;
            default: aw_hsk = 1'b0;
        endcase

        case ({s_axi_wvalid, s_axi_wready})
            2'b11: w_hsk = 1'b1;
            default: w_hsk = 1'b0;
        endcase

        case ({s_axi_arvalid, s_axi_arready})
            2'b11: ar_hsk = 1'b1;
            default: ar_hsk = 1'b0;
        endcase

        // Calculate is_write and is_read
        case ({s_axi_awvalid, current_state == ACCESS})
            2'b10, 2'b11, 2'b01: is_write = 1'b1;
            default: is_write = 1'b0;
        endcase

        case ({s_axi_arvalid, current_state == ACCESS})
            2'b10, 2'b11, 2'b01: is_read = 1'b1;
            default: is_read = 1'b0;
        endcase

        // State transition logic
        case (current_state)
            IDLE: begin
                case ({s_axi_awvalid, s_axi_arvalid})
                    2'b10, 2'b11: next_state = SETUP;
                    2'b01:        next_state = SETUP;
                    default:      next_state = IDLE;
                endcase
            end

            SETUP: begin
                case (m_apb_pready)
                    1'b1: next_state = ACCESS;
                    default: next_state = SETUP;
                endcase
            end

            ACCESS: begin
                case (m_apb_pready)
                    1'b1: next_state = RESPONSE;
                    default: next_state = ACCESS;
                endcase
            end

            RESPONSE: begin
                case ({is_write && s_axi_bready, is_read && s_axi_rready})
                    2'b10, 2'b11, 2'b01: next_state = IDLE;
                    default: next_state = RESPONSE;
                endcase
            end
        endcase
    end

    // Block 4: APB Control Logic
    always_comb begin
        m_apb_paddr = 32'b0;
        m_apb_psel = 1'b0;
        m_apb_penable = 1'b0;
        m_apb_pwrite = 1'b0;
        m_apb_pwdata = 32'b0;

        case (current_state)
            SETUP, ACCESS: begin
                m_apb_psel = 1'b1;
                m_apb_paddr = addr_reg;
                m_apb_pwrite = write_reg;
                m_apb_pwdata = s_axi_wdata;
                case (current_state)
                    ACCESS: m_apb_penable = 1'b1;
                    default: m_apb_penable = 1'b0;
                endcase
            end
        endcase
    end

    // Block 5: AXI Handshake Logic
    always_comb begin
        s_axi_awready = 1'b0;
        s_axi_wready  = 1'b0;
        s_axi_arready = 1'b0;
        s_axi_bvalid  = 1'b0;
        s_axi_rvalid  = 1'b0;
        s_axi_bresp   = 2'b00;
        s_axi_rresp   = 2'b00;
        s_axi_rdata   = 32'b0;

        case (current_state)
            IDLE: begin
                s_axi_awready = 1'b1;
                s_axi_wready  = 1'b1;
                s_axi_arready = 1'b1;
            end

            RESPONSE: begin
                case (is_write)
                    1'b1: begin
                        s_axi_bvalid = 1'b1;
                        case (m_apb_pslverr)
                            1'b1: s_axi_bresp = 2'b10;
                            default: s_axi_bresp = 2'b00;
                        endcase
                    end
                    1'b0: begin
                        s_axi_rvalid = 1'b1;
                        s_axi_rdata  = m_apb_prdata;
                        case (m_apb_pslverr)
                            1'b1: s_axi_rresp = 2'b10;
                            default: s_axi_rresp = 2'b00;
                        endcase
                    end
                endcase
            end
        endcase
    end

endmodule,"module axi2apb_bridge_assertions()

module crc32_engine (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        data_valid,
    input  logic [31:0] data_in,
    input  logic        crc_init,
    output logic [31:0] crc_out,
    output logic        crc_valid
);

    // Polynomial: 0x04C11DB7 (Ethernet/PCIe)
    localparam CRC_POLY = 32'h04C11DB7;

    // Block 1: CRC Register (Case-only Sequential)
    logic [31:0] crc_reg;
    logic [31:0] crc_next;

    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: crc_reg <= 32'hFFFFFFFF;
            1'b1: begin
                case ({crc_init, data_valid})
                    2'b10, 2'b11: crc_reg <= 32'hFFFFFFFF;  // Init takes priority
                    2'b01:        crc_reg <= crc_next;
                    default:      crc_reg <= crc_reg;
                endcase
            end
        endcase
    end

    // Block 2: Parallel CRC Computation (Combinational)
    always_comb begin
        logic [31:0] data_xor;
        data_xor = data_in ^ crc_reg;

        // Parallel CRC calculation using case for each bit
        // Bit 0
        case (1'b1)
            1'b1: crc_next[0] = data_xor[31] ^ data_xor[29] ^ data_xor[28] ^ data_xor[26] ^
                                 data_xor[25] ^ data_xor[22] ^ data_xor[21] ^ data_xor[20] ^
                                 data_xor[19] ^ data_xor[18] ^ data_xor[17] ^ data_xor[16] ^
                                 data_xor[14] ^ data_xor[13] ^ data_xor[12] ^ data_xor[11] ^
                                 data_xor[9]  ^ data_xor[8]  ^ data_xor[7]  ^ data_xor[5]  ^
                                 data_xor[4]  ^ data_xor[3]  ^ data_xor[0];
        endcase

        // Bit 1
        case (1'b1)
            1'b1: crc_next[1] = data_xor[30] ^ data_xor[28] ^ data_xor[27] ^ data_xor[25] ^
                                 data_xor[24] ^ data_xor[21] ^ data_xor[20] ^ data_xor[19] ^
                                 data_xor[18] ^ data_xor[17] ^ data_xor[16] ^ data_xor[15] ^
                                 data_xor[13] ^ data_xor[12] ^ data_xor[11] ^ data_xor[10] ^
                                 data_xor[8]  ^ data_xor[7]  ^ data_xor[6]  ^ data_xor[4]  ^
                                 data_xor[3]  ^ data_xor[2]  ^ data_xor[1];
        endcase

        // Bit 31
        case (1'b1)
            1'b1: crc_next[31] = data_xor[28] ^ data_xor[27] ^ data_xor[26] ^ data_xor[25] ^
                                 data_xor[24] ^ data_xor[23] ^ data_xor[22] ^ data_xor[21] ^
                                 data_xor[20] ^ data_xor[19] ^ data_xor[18] ^ data_xor[17] ^
                                 data_xor[16] ^ data_xor[15] ^ data_xor[14] ^ data_xor[13] ^
                                 data_xor[12] ^ data_xor[11] ^ data_xor[10] ^ data_xor[9]  ^
                                 data_xor[8]  ^ data_xor[7]  ^ data_xor[6]  ^ data_xor[5]  ^
                                 data_xor[4]  ^ data_xor[3]  ^ data_xor[2]  ^ data_xor[1];
        endcase
    end

    // Block 3: Output Control (Case-only Combinational)
    always_comb begin
        case (data_valid)
            1'b1: begin
                crc_out = ~crc_reg;
                crc_valid = 1'b1;
            end
            default: begin
                crc_out = 32'b0;
                crc_valid = 1'b0;
            end
        endcase
    end

    // Block 4: Error Detection (Case-only Combinational)
    logic [31:0] expected_crc;
    logic crc_error;

    always_comb begin
        expected_crc = 32'hDEBB20E3;
        case (crc_out != expected_crc && crc_valid)
            1'b1: crc_error = 1'b1;
            default: crc_error = 1'b0;
        endcase
    end

endmodule,"module crc32_engine_assertions(

// DDR3 Memory Controller Command Scheduler
// Uses ONLY case statements - no if/else, no loops
// Manages command priority, bank state machine, and timing constraints

module ddr3_cmd_scheduler (
    input  logic        clk,
    input  logic        rst_n,

    // Command interface from controller
    input  logic [2:0]  cmd_type,      // 0:ACT, 1:RD, 2:WR, 3:PRE, 4:REF, 5:ZQ
    input  logic [2:0]  bank_addr,
    input  logic [14:0] row_addr,
    input  logic        cmd_valid,
    output logic        cmd_ready,

    // Command output to PHY
    output logic [2:0]  phy_cmd_type,
    output logic [2:0]  phy_bank_addr,
    output logic [14:0] phy_row_addr,
    output logic        phy_cmd_valid,
    input  logic        phy_cmd_accept,

    // Bank status
    input  logic [7:0]  bank_active_row [7:0],  // Current open row per bank
    input  logic [7:0]  bank_state      [7:0],  // 0:idle, 1:active, 2:precharging
    input  logic [7:0]  bank_timer      [7:0]   // Timing constraint counters
);

    //=========================================================================
    // Local parameters
    //=========================================================================
    localparam CMD_ACT = 3'd0;
    localparam CMD_RD  = 3'd1;
    localparam CMD_WR  = 3'd2;
    localparam CMD_PRE = 3'd3;
    localparam CMD_REF = 3'd4;
    localparam CMD_ZQ  = 3'd5;

    localparam BANK_IDLE       = 3'd0;
    localparam BANK_ACTIVE     = 3'd1;
    localparam BANK_PRECHARGING = 3'd2;

    localparam SCHED_IDLE      = 2'd0;
    localparam SCHED_CHECK     = 2'd1;
    localparam SCHED_ISSUE     = 2'd2;
    localparam SCHED_WAIT      = 2'd3;

    //=========================================================================
    // Internal signals
    //=========================================================================
    logic [1:0]  sched_state;
    logic [2:0]  selected_bank;
    logic [2:0]  pending_cmd_type;
    logic [2:0]  pending_bank;
    logic [14:0] pending_row;
    logic        pending_valid;

    logic [2:0]  arbitration_result;
    logic        bank_match;
    logic        row_match;
    logic        bank_ready;
    logic [7:0]  bank_active_row_local;
    logic [7:0]  bank_state_local;
    logic [7:0]  bank_timer_local;

    //=========================================================================
    // Block 1: Combinational - Command Arbitration
    // Selects highest priority command from pending queue
    // Uses case statement for priority encoding
    //=========================================================================
    always_comb begin
        // Default values
        arbitration_result = 3'd0;

        // Priority encoder using nested case statements
        // Priority: REF > ZQ > ACT > PRE > WR > RD
        case (cmd_valid)
            1'b1: begin
                case (cmd_type)
                    CMD_REF: arbitration_result = CMD_REF;
                    CMD_ZQ:  arbitration_result = CMD_ZQ;
                    CMD_ACT: arbitration_result = CMD_ACT;
                    CMD_PRE: arbitration_result = CMD_PRE;
                    CMD_WR:  arbitration_result = CMD_WR;
                    CMD_RD:  arbitration_result = CMD_RD;
                    default: arbitration_result = CMD_RD;
                endcase
            end
            default: arbitration_result = 3'b111;  // No command
        endcase
    end

    //=========================================================================
    // Block 2: Combinational - Bank Status Evaluation
    // Determines if selected bank can accept the command
    // Uses case statements for bank state and timing checks
    //=========================================================================
    always_comb begin
        // Extract bank-specific signals
        case (pending_bank)
            3'd0: begin
                bank_active_row_local = bank_active_row[0];
                bank_state_local = bank_state[0];
                bank_timer_local = bank_timer[0];
            end
            3'd1: begin
                bank_active_row_local = bank_active_row[1];
                bank_state_local = bank_state[1];
                bank_timer_local = bank_timer[1];
            end
            3'd2: begin
                bank_active_row_local = bank_active_row[2];
                bank_state_local = bank_state[2];
                bank_timer_local = bank_timer[2];
            end
            3'd3: begin
                bank_active_row_local = bank_active_row[3];
                bank_state_local = bank_state[3];
                bank_timer_local = bank_timer[3];
            end
            3'd4: begin
                bank_active_row_local = bank_active_row[4];
                bank_state_local = bank_state[4];
                bank_timer_local = bank_timer[4];
            end
            3'd5: begin
                bank_active_row_local = bank_active_row[5];
                bank_state_local = bank_state[5];
                bank_timer_local = bank_timer[5];
            end
            3'd6: begin
                bank_active_row_local = bank_active_row[6];
                bank_state_local = bank_state[6];
                bank_timer_local = bank_timer[6];
            end
            default: begin
                bank_active_row_local = bank_active_row[7];
                bank_state_local = bank_state[7];
                bank_timer_local = bank_timer[7];
            end
        endcase

        // Check if row matches open row
        row_match = (bank_active_row_local == pending_row);

        // Check if bank is ready based on state and timer
        case (bank_state_local)
            BANK_IDLE: begin
                case (pending_cmd_type)
                    CMD_ACT: bank_ready = (bank_timer_local == 8'd0);  // tRRD check
                    CMD_REF: bank_ready = (bank_timer_local == 8'd0);  // tRC check
                    default: bank_ready = 1'b0;  // Can't do RD/WR on idle bank
                endcase
            end
            BANK_ACTIVE: begin
                case (pending_cmd_type)
                    CMD_RD, CMD_WR: begin
                        case (row_match)
                            1'b1: bank_ready = (bank_timer_local == 8'd0);  // tRCD satisfied
                            1'b0: bank_ready = 1'b0;  // Need PRE first
                        endcase
                    end
                    CMD_PRE: bank_ready = (bank_timer_local == 8'd0);  // tRAS satisfied
                    default: bank_ready = 1'b0;
                endcase
            end
            BANK_PRECHARGING: begin
                case (pending_cmd_type)
                    CMD_ACT: bank_ready = (bank_timer_local == 8'd0);  // tRP satisfied
                    default: bank_ready = 1'b0;
                endcase
            end
            default: bank_ready = 1'b0;
        endcase
    end

    //=========================================================================
    // Block 3: Sequential - Command Pending Register
    // Latches incoming command when accepted
    // Uses case for state-based latching
    //=========================================================================
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                pending_cmd_type <= 3'd0;
                pending_bank     <= 3'd0;
                pending_row      <= 15'd0;
                pending_valid    <= 1'b0;
                cmd_ready        <= 1'b1;
            end
            1'b1: begin
                case (sched_state)
                    SCHED_IDLE: begin
                        // Accept new command when scheduler idle
                        case (cmd_valid)
                            1'b1: begin
                                pending_cmd_type <= arbitration_result;
                                pending_bank     <= bank_addr;
                                pending_row      <= row_addr;
                                pending_valid    <= 1'b1;
                                cmd_ready        <= 1'b0;
                            end
                            default: begin
                                pending_valid    <= 1'b0;
                                cmd_ready        <= 1'b1;
                                // Preserve existing values for other registers
                                pending_cmd_type <= pending_cmd_type;
                                pending_bank     <= pending_bank;
                                pending_row      <= pending_row;
                            end
                        endcase
                    end
                    SCHED_ISSUE: begin
                        // Command issued, clear pending
                        case (phy_cmd_accept)
                            1'b1: begin
                                pending_valid <= 1'b0;
                                cmd_ready     <= 1'b1;
                                // Preserve existing values for other registers
                                pending_cmd_type <= pending_cmd_type;
                                pending_bank     <= pending_bank;
                                pending_row      <= pending_row;
                            end
                            default: begin
                                pending_valid <= pending_valid;
                                cmd_ready     <= 1'b0;
                                // Preserve existing values for all registers
                                pending_cmd_type <= pending_cmd_type;
                                pending_bank     <= pending_bank;
                                pending_row      <= pending_row;
                            end
                        endcase
                    end
                    default: begin
                        // Keep pending during check/wait states
                        pending_valid <= pending_valid;
                        cmd_ready     <= 1'b0;
                        // Preserve existing values for all registers
                        pending_cmd_type <= pending_cmd_type;
                        pending_bank     <= pending_bank;
                        pending_row      <= pending_row;
                    end
                endcase
            end
        endcase
    end

    //=========================================================================
    // Block 4: Sequential - Scheduler FSM
    // Manages command issuance flow using case statements
    //=========================================================================
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                sched_state   <= SCHED_IDLE;
                phy_cmd_type  <= 3'd0;
                phy_bank_addr <= 3'd0;
                phy_row_addr  <= 15'd0;
                phy_cmd_valid <= 1'b0;
            end
            1'b1: begin
                case (sched_state)
                    SCHED_IDLE: begin
                        phy_cmd_valid <= 1'b0;
                        case (pending_valid)
                            1'b1: sched_state <= SCHED_CHECK;
                            default: sched_state <= SCHED_IDLE;
                        endcase
                    end

                    SCHED_CHECK: begin
                        phy_cmd_valid <= 1'b0;
                        // Evaluate if command can be issued based on bank status
                        case (bank_ready)
                            1'b1: sched_state <= SCHED_ISSUE;
                            1'b0: begin
                                // Need to insert auto-precharge if row mismatch
                                case ({pending_cmd_type, bank_state_local, row_match})
                                    {CMD_RD, BANK_ACTIVE, 1'b0},
                                    {CMD_WR, BANK_ACTIVE, 1'b0}: begin
                                        // Auto-generate precharge command
                                        phy_cmd_type  <= CMD_PRE;
                                        phy_bank_addr <= pending_bank;
                                        phy_row_addr  <= 15'd0;
                                        phy_cmd_valid <= 1'b1;
                                        sched_state   <= SCHED_WAIT;
                                    end
                                    default: begin
                                        sched_state <= SCHED_WAIT;
                                    end
                                endcase
                            end
                        endcase
                    end

                    SCHED_ISSUE: begin
                        // Issue the pending command
                        case (pending_valid)
                            1'b1: begin
                                phy_cmd_type  <= pending_cmd_type;
                                phy_bank_addr <= pending_bank;
                                phy_row_addr  <= pending_row;
                                phy_cmd_valid <= 1'b1;

                                case (phy_cmd_accept)
                                    1'b1: sched_state <= SCHED_IDLE;
                                    default: sched_state <= SCHED_ISSUE;
                                endcase
                            end
                            default: begin
                                sched_state <= SCHED_IDLE;
                            end
                        endcase
                    end

                    SCHED_WAIT: begin
                        // Wait for timing constraints
                        case (phy_cmd_accept)
                            1'b1: begin
                                phy_cmd_valid <= 1'b0;
                                sched_state   <= SCHED_IDLE;
                            end
                            default: begin
                                phy_cmd_valid <= phy_cmd_valid;
                                sched_state   <= SCHED_WAIT;
                            end
                        endcase
                    end

                    default: begin
                        sched_state <= SCHED_IDLE;
                    end
                endcase
            end
        endcase
    end

endmodule,"module ddr3_cmd_scheduler (

module ethernet_packet_parser (
    input  logic        clk,
    input  logic        rst_n,

    // Input data stream
    input  logic        data_valid,
    input  logic [63:0] data_in,      // 64-bit wide data (8 bytes per cycle)
    input  logic        data_start,    // SOP (Start of Packet)
    input  logic        data_end,      // EOP (End of Packet)

    // Output parsed fields
    output logic [47:0] dest_mac,
    output logic [47:0] src_mac,
    output logic [15:0] ethertype,
    output logic [31:0] ipv4_src,
    output logic [31:0] ipv4_dst,
    output logic [15:0] tcp_src_port,
    output logic [15:0] tcp_dst_port,
    output logic [7:0]  ip_protocol,
    output logic        packet_valid,

    // Control outputs
    output logic        ipv4_detected,
    output logic        tcp_detected,
    output logic        udp_detected,
    output logic        vlan_detected,
    output logic        parsing_error
);

    // Block 1: Packet State Machine (Sequential)
    typedef enum logic [2:0] {
        WAIT_SOP   = 3'b000,
        MAC_DEST   = 3'b001,
        MAC_SRC    = 3'b010,
        VLAN_TAG   = 3'b011,
        ETHERTYPE  = 3'b100,
        IP_HEADER  = 3'b101,
        L4_HEADER  = 3'b110,
        PAYLOAD    = 3'b111
    } parse_state_t;

    parse_state_t current_state, next_state;
    logic [4:0] byte_offset;           // Byte position within current 64-bit word (0-7, but 5 bits to avoid overflow)
    logic [5:0] header_byte_count;     // Count of bytes processed in current header (up to 40 bytes for IP header)
    logic [47:0] temp_dest_mac;
    logic [47:0] temp_src_mac;
    logic [15:0] temp_ethertype;
    logic [31:0] temp_ipv4_src;
    logic [31:0] temp_ipv4_dst;
    logic [7:0]  temp_ip_protocol;
    logic [15:0] temp_tcp_src;
    logic [15:0] temp_tcp_dst;
    logic        has_vlan;

    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: current_state <= WAIT_SOP;
            1'b1: current_state <= next_state;
        endcase
    end

    // Block 2: Byte Position and Counters (Sequential)
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                byte_offset <= 5'b0;
                header_byte_count <= 6'b0;
            end
            1'b1: begin
                case (current_state)
                    WAIT_SOP: begin
                        case (data_start)
                            1'b1: begin
                                byte_offset <= 5'b0;
                                header_byte_count <= 6'b0;
                            end
                            default: begin
                                byte_offset <= byte_offset;
                                header_byte_count <= header_byte_count;
                            end
                        endcase
                    end

                    MAC_DEST, MAC_SRC, VLAN_TAG, ETHERTYPE, IP_HEADER, L4_HEADER: begin
                        case (data_valid)
                            1'b1: begin
                                byte_offset <= byte_offset + 5'd8;
                                header_byte_count <= header_byte_count + 6'd8;
                            end
                            default: begin
                                byte_offset <= byte_offset;
                                header_byte_count <= header_byte_count;
                            end
                        endcase
                    end

                    default: begin
                        byte_offset <= byte_offset;
                        header_byte_count <= header_byte_count;
                    end
                endcase
            end
        endcase
    end

    // Block 3: State Transition Logic (Case-only Combinational)
    always_comb begin
        next_state = current_state;

        case (current_state)
            WAIT_SOP: begin
                case (data_start)
                    1'b1: next_state = MAC_DEST;
                    default: next_state = WAIT_SOP;
                endcase
            end

            MAC_DEST: begin
                case ({data_valid, (header_byte_count >= 6'd6)})
                    2'b11: next_state = MAC_SRC;
                    default: next_state = MAC_DEST;
                endcase
            end

            MAC_SRC: begin
                case ({data_valid, (header_byte_count >= 6'd12)})
                    2'b11: next_state = ETHERTYPE;
                    default: next_state = MAC_SRC;
                endcase
            end

            ETHERTYPE: begin
                case (data_valid)
                    1'b1: begin
                        case (temp_ethertype)
                            16'h8100: next_state = VLAN_TAG;  // VLAN tag detected
                            default: next_state = IP_HEADER;
                        endcase
                    end
                    default: next_state = ETHERTYPE;
                endcase
            end

            VLAN_TAG: begin
                case ({data_valid, (header_byte_count >= 6'd4)})
                    2'b11: next_state = ETHERTYPE;
                    default: next_state = VLAN_TAG;
                endcase
            end

            IP_HEADER: begin
                case ({data_valid, (header_byte_count >= 6'd20)})
                    2'b11: next_state = L4_HEADER;
                    default: next_state = IP_HEADER;
                endcase
            end

            L4_HEADER: begin
                case (data_valid)
                    1'b1: begin
                        case ({temp_ip_protocol, (header_byte_count >= 6'd4)})
                            {8'd6, 1'b1}: next_state = PAYLOAD;  // TCP
                            {8'd17, 1'b1}: next_state = PAYLOAD;  // UDP
                            default: next_state = L4_HEADER;
                        endcase
                    end
                    default: next_state = L4_HEADER;
                endcase
            end

            PAYLOAD: begin
                case (data_end)
                    1'b1: next_state = WAIT_SOP;
                    default: next_state = PAYLOAD;
                endcase
            end

            default: begin
                case (data_end)
                    1'b1: next_state = WAIT_SOP;
                    default: next_state = current_state;
                endcase
            end
        endcase
    end

    // Block 4: MAC Address Extraction (Combinational with Byte Alignment)
    always_comb begin
        temp_dest_mac = dest_mac;
        temp_src_mac = src_mac;

        case (current_state)
            MAC_DEST: begin
                case (byte_offset[2:0])  // Extract based on byte alignment (lower 3 bits only)
                    3'b000: begin
                        temp_dest_mac[47:40] = data_in[63:56];
                        temp_dest_mac[39:32] = data_in[55:48];
                        temp_dest_mac[31:24] = data_in[47:40];
                        temp_dest_mac[23:16] = data_in[39:32];
                        temp_dest_mac[15:8]  = data_in[31:24];
                        temp_dest_mac[7:0]   = data_in[23:16];
                    end
                    3'b001: begin
                        temp_dest_mac[47:40] = data_in[55:48];
                        temp_dest_mac[39:32] = data_in[47:40];
                        temp_dest_mac[31:24] = data_in[39:32];
                        temp_dest_mac[23:16] = data_in[31:24];
                        temp_dest_mac[15:8]  = data_in[23:16];
                        temp_dest_mac[7:0]   = data_in[15:8];
                    end
                    default: temp_dest_mac = temp_dest_mac;
                endcase
            end

            MAC_SRC: begin
                case (byte_offset[2:0])
                    3'b000: begin
                        temp_src_mac[47:40] = data_in[63:56];
                        temp_src_mac[39:32] = data_in[55:48];
                        temp_src_mac[31:24] = data_in[47:40];
                        temp_src_mac[23:16] = data_in[39:32];
                        temp_src_mac[15:8]  = data_in[31:24];
                        temp_src_mac[7:0]   = data_in[23:16];
                    end
                    3'b001: begin
                        temp_src_mac[47:40] = data_in[55:48];
                        temp_src_mac[39:32] = data_in[47:40];
                        temp_src_mac[31:24] = data_in[39:32];
                        temp_src_mac[23:16] = data_in[31:24];
                        temp_src_mac[15:8]  = data_in[23:16];
                        temp_src_mac[7:0]   = data_in[15:8];
                    end
                    default: temp_src_mac = temp_src_mac;
                endcase
            end

            default: begin
                temp_dest_mac = temp_dest_mac;
                temp_src_mac = temp_src_mac;
            end
        endcase
    end

    // Block 5: Ethertype and VLAN Detection (Sequential Register)
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                temp_ethertype <= 16'b0;
                has_vlan <= 1'b0;
                vlan_detected <= 1'b0;
            end
            1'b1: begin
                case (current_state)
                    ETHERTYPE: begin
                        case (data_valid)
                            1'b1: begin
                                case (byte_offset[2:0])
                                    3'b000: begin
                                        temp_ethertype[15:8] <= data_in[63:56];
                                        temp_ethertype[7:0]  <= data_in[55:48];
                                    end
                                    3'b001: begin
                                        temp_ethertype[15:8] <= data_in[55:48];
                                        temp_ethertype[7:0]  <= data_in[47:40];
                                    end
                                    default: temp_ethertype <= temp_ethertype;
                                endcase
                            end
                            default: temp_ethertype <= temp_ethertype;
                        endcase

                        case (temp_ethertype)
                            16'h8100: begin
                                has_vlan <= 1'b1;
                                vlan_detected <= 1'b1;
                            end
                            default: begin
                                has_vlan <= has_vlan;
                                vlan_detected <= vlan_detected;
                            end
                        endcase
                    end

                    default: begin
                        temp_ethertype <= temp_ethertype;
                        has_vlan <= has_vlan;
                        vlan_detected <= vlan_detected;
                    end
                endcase
            end
        endcase
    end

    // Block 6: IPv4 Header Extraction (Sequential with Byte Selection)
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                temp_ipv4_src <= 32'b0;
                temp_ipv4_dst <= 32'b0;
                temp_ip_protocol <= 8'b0;
                ipv4_detected <= 1'b0;
            end
            1'b1: begin
                case (current_state)
                    IP_HEADER: begin
                        case (header_byte_count)
                            6'd8: begin  // Protocol field at offset 9
                                case (byte_offset[2:0])
                                    3'b000: temp_ip_protocol <= data_in[55:48];
                                    3'b001: temp_ip_protocol <= data_in[47:40];
                                    default: temp_ip_protocol <= temp_ip_protocol;
                                endcase
                            end

                            6'd12: begin  // Source IP at offset 12
                                case (byte_offset[2:0])
                                    3'b000: begin
                                        temp_ipv4_src[31:24] <= data_in[63:56];
                                        temp_ipv4_src[23:16] <= data_in[55:48];
                                        temp_ipv4_src[15:8]  <= data_in[47:40];
                                        temp_ipv4_src[7:0]   <= data_in[39:32];
                                    end
                                    3'b001: begin
                                        temp_ipv4_src[31:24] <= data_in[55:48];
                                        temp_ipv4_src[23:16] <= data_in[47:40];
                                        temp_ipv4_src[15:8]  <= data_in[39:32];
                                        temp_ipv4_src[7:0]   <= data_in[31:24];
                                    end
                                    default: temp_ipv4_src <= temp_ipv4_src;
                                endcase
                            end

                            6'd16: begin  // Destination IP at offset 16
                                case (byte_offset[2:0])
                                    3'b000: begin
                                        temp_ipv4_dst[31:24] <= data_in[63:56];
                                        temp_ipv4_dst[23:16] <= data_in[55:48];
                                        temp_ipv4_dst[15:8]  <= data_in[47:40];
                                        temp_ipv4_dst[7:0]   <= data_in[39:32];
                                    end
                                    3'b001: begin
                                        temp_ipv4_dst[31:24] <= data_in[55:48];
                                        temp_ipv4_dst[23:16] <= data_in[47:40];
                                        temp_ipv4_dst[15:8]  <= data_in[39:32];
                                        temp_ipv4_dst[7:0]   <= data_in[31:24];
                                    end
                                    default: temp_ipv4_dst <= temp_ipv4_dst;
                                endcase
                            end

                            default: begin
                                temp_ipv4_src <= temp_ipv4_src;
                                temp_ipv4_dst <= temp_ipv4_dst;
                                temp_ip_protocol <= temp_ip_protocol;
                            end
                        endcase

                        case (temp_ethertype)
                            16'h0800: ipv4_detected <= 1'b1;
                            default: ipv4_detected <= ipv4_detected;
                        endcase
                    end

                    default: begin
                        temp_ipv4_src <= temp_ipv4_src;
                        temp_ipv4_dst <= temp_ipv4_dst;
                        temp_ip_protocol <= temp_ip_protocol;
                        ipv4_detected <= ipv4_detected;
                    end
                endcase
            end
        endcase
    end

    // Block 7: TCP/UDP Port Extraction (Sequential)
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                temp_tcp_src <= 16'b0;
                temp_tcp_dst <= 16'b0;
                tcp_detected <= 1'b0;
                udp_detected <= 1'b0;
            end
            1'b1: begin
                case (current_state)
                    L4_HEADER: begin
                        case (header_byte_count)
                            6'd0: begin  // Source port at offset 0
                                case (byte_offset[2:0])
                                    3'b000: begin
                                        temp_tcp_src[15:8] <= data_in[63:56];
                                        temp_tcp_src[7:0]  <= data_in[55:48];
                                    end
                                    3'b001: begin
                                        temp_tcp_src[15:8] <= data_in[55:48];
                                        temp_tcp_src[7:0]  <= data_in[47:40];
                                    end
                                    default: temp_tcp_src <= temp_tcp_src;
                                endcase
                            end

                            6'd2: begin  // Destination port at offset 2
                                case (byte_offset[2:0])
                                    3'b000: begin
                                        temp_tcp_dst[15:8] <= data_in[63:56];
                                        temp_tcp_dst[7:0]  <= data_in[55:48];
                                    end
                                    3'b001: begin
                                        temp_tcp_dst[15:8] <= data_in[55:48];
                                        temp_tcp_dst[7:0]  <= data_in[47:40];
                                    end
                                    default: temp_tcp_dst <= temp_tcp_dst;
                                endcase
                            end

                            default: begin
                                temp_tcp_src <= temp_tcp_src;
                                temp_tcp_dst <= temp_tcp_dst;
                            end
                        endcase

                        case (temp_ip_protocol)
                            8'd6:  tcp_detected <= 1'b1;
                            8'd17: udp_detected <= 1'b1;
                            default: begin
                                tcp_detected <= tcp_detected;
                                udp_detected <= udp_detected;
                            end
                        endcase
                    end

                    default: begin
                        temp_tcp_src <= temp_tcp_src;
                        temp_tcp_dst <= temp_tcp_dst;
                        tcp_detected <= tcp_detected;
                        udp_detected <= udp_detected;
                    end
                endcase
            end
        endcase
    end

    // Block 8: Output Assignment and Error Detection (Case-only Combinational)
    always_comb begin
        dest_mac = temp_dest_mac;
        src_mac = temp_src_mac;
        ethertype = temp_ethertype;
        ipv4_src = temp_ipv4_src;
        ipv4_dst = temp_ipv4_dst;
        tcp_src_port = temp_tcp_src;
        tcp_dst_port = temp_tcp_dst;
        ip_protocol = temp_ip_protocol;
        packet_valid = 1'b0;
        parsing_error = 1'b0;

        case (current_state)
            PAYLOAD: begin
                case (data_end)
                    1'b1: packet_valid = 1'b1;
                    default: packet_valid = 1'b0;
                endcase
            end

            default: begin
                case (current_state == WAIT_SOP && data_end && !data_start)
                    1'b1: parsing_error = 1'b1;
                    default: parsing_error = 1'b0;
                endcase
            end
        endcase
    end

endmodule,"assert (dest_mac == expected_dest_mac), ""Destination MAC address assertion failed""

module video_csc (
    input  logic        clk,
    input  logic        rst_n,
    input  logic [23:0] rgb_pixel,       // RGB 888 {R[7:0], G[7:0], B[7:0]}
    input  logic        pixel_valid,
    output logic [29:0] ycbcr_pixel,     // YCbCr 4:4:4 {Y[9:0], Cb[9:0], Cr[9:0]}
    output logic [9:0]  h_sync, v_sync,
    output logic        h_blank, v_blank
);

    // Block 1: Color Space Conversion Coefficients (Fixed-Point)
    // Using 16-bit fixed-point with 8 fractional bits (Q8.8)
    // Y  = (77*R + 150*G + 29*B) >> 8
    // Cb = (-43*R - 85*G + 128*B + 32768) >> 8
    // Cr = (128*R - 107*G - 21*B + 32768) >> 8

    // Block 1a: RGB Component Extraction
    logic [7:0] R, G, B;

    always_comb begin
        R = rgb_pixel[23:16];
        G = rgb_pixel[15:8];
        B = rgb_pixel[7:0];
    end

    // Block 2: Y Component Calculation (Sequential Pipeline Stage 1)
    logic [15:0] R_mul_77, G_mul_150, B_mul_29;
    logic [15:0] y_sum_stage1;

    always_comb begin
        // Multiply using case-based partial products (no multipliers)
        case (R)
            8'd0:   R_mul_77 = 16'd0;
            8'd1:   R_mul_77 = 16'd77;
            8'd2:   R_mul_77 = 16'd154;
            8'd3:   R_mul_77 = 16'd231;
            8'd4:   R_mul_77 = 16'd308;
            8'd5:   R_mul_77 = 16'd385;
            8'd6:   R_mul_77 = 16'd462;
            8'd7:   R_mul_77 = 16'd539;
            8'd8:   R_mul_77 = 16'd616;
            8'd9:   R_mul_77 = 16'd693;
            8'd10:  R_mul_77 = 16'd770;
            8'd11:  R_mul_77 = 16'd847;
            8'd12:  R_mul_77 = 16'd924;
            8'd13:  R_mul_77 = 16'd1001;
            8'd14:  R_mul_77 = 16'd1078;
            8'd15:  R_mul_77 = 16'd1155;
            8'd16:  R_mul_77 = 16'd1232;
            8'd17:  R_mul_77 = 16'd1309;
            8'd18:  R_mul_77 = 16'd1386;
            8'd19:  R_mul_77 = 16'd1463;
            8'd20:  R_mul_77 = 16'd1540;
            8'd21:  R_mul_77 = 16'd1617;
            8'd22:  R_mul_77 = 16'd1694;
            8'd23:  R_mul_77 = 16'd1771;
            8'd24:  R_mul_77 = 16'd1848;
            8'd25:  R_mul_77 = 16'd1925;
            8'd26:  R_mul_77 = 16'd2002;
            8'd27:  R_mul_77 = 16'd2079;
            8'd28:  R_mul_77 = 16'd2156;
            8'd29:  R_mul_77 = 16'd2233;
            8'd30:  R_mul_77 = 16'd2310;
            8'd31:  R_mul_77 = 16'd2387;
            8'd32:  R_mul_77 = 16'd2464;
            8'd33:  R_mul_77 = 16'd2541;
            8'd34:  R_mul_77 = 16'd2618;
            8'd35:  R_mul_77 = 16'd2695;
            8'd36:  R_mul_77 = 16'd2772;
            8'd37:  R_mul_77 = 16'd2849;
            8'd38:  R_mul_77 = 16'd2926;
            8'd39:  R_mul_77 = 16'd3003;
            8'd40:  R_mul_77 = 16'd3080;
            8'd41:  R_mul_77 = 16'd3157;
            8'd42:  R_mul_77 = 16'd3234;
            8'd43:  R_mul_77 = 16'd3311;
            8'd44:  R_mul_77 = 16'd3388;
            8'd45:  R_mul_77 = 16'd3465;
            8'd46:  R_mul_77 = 16'd3542;
            8'd47:  R_mul_77 = 16'd3619;
            8'd48:  R_mul_77 = 16'd3696;
            8'd49:  R_mul_77 = 16'd3773;
            8'd50:  R_mul_77 = 16'd3850;
            8'd51:  R_mul_77 = 16'd3927;
            8'd52:  R_mul_77 = 16'd4004;
            8'd53:  R_mul_77 = 16'd4081;
            8'd54:  R_mul_77 = 16'd4158;
            8'd55:  R_mul_77 = 16'd4235;
            8'd56:  R_mul_77 = 16'd4312;
            8'd57:  R_mul_77 = 16'd4389;
            8'd58:  R_mul_77 = 16'd4466;
            8'd59:  R_mul_77 = 16'd4543;
            8'd60:  R_mul_77 = 16'd4620;
            8'd61:  R_mul_77 = 16'd4697;
            8'd62:  R_mul_77 = 16'd4774;
            8'd63:  R_mul_77 = 16'd4851;
            8'd64:  R_mul_77 = 16'd4928;
            8'd65:  R_mul_77 = 16'd5005;
            8'd66:  R_mul_77 = 16'd5082;
            8'd67:  R_mul_77 = 16'd5159;
            8'd68:  R_mul_77 = 16'd5236;
            8'd69:  R_mul_77 = 16'd5313;
            8'd70:  R_mul_77 = 16'd5390;
            8'd71:  R_mul_77 = 16'd5467;
            8'd72:  R_mul_77 = 16'd5544;
            8'd73:  R_mul_77 = 16'd5621;
            8'd74:  R_mul_77 = 16'd5698;
            8'd75:  R_mul_77 = 16'd5775;
            8'd76:  R_mul_77 = 16'd5852;
            8'd77:  R_mul_77 = 16'd5929;
            8'd78:  R_mul_77 = 16'd6006;
            8'd79:  R_mul_77 = 16'd6083;
            8'd80:  R_mul_77 = 16'd6160;
            8'd81:  R_mul_77 = 16'd6237;
            8'd82:  R_mul_77 = 16'd6314;
            8'd83:  R_mul_77 = 16'd6391;
            8'd84:  R_mul_77 = 16'd6468;
            8'd85:  R_mul_77 = 16'd6545;
            8'd86:  R_mul_77 = 16'd6622;
            8'd87:  R_mul_77 = 16'd6699;
            8'd88:  R_mul_77 = 16'd6776;
            8'd89:  R_mul_77 = 16'd6853;
            8'd90:  R_mul_77 = 16'd6930;
            8'd91:  R_mul_77 = 16'd7007;
            8'd92:  R_mul_77 = 16'd7084;
            8'd93:  R_mul_77 = 16'd7161;
            8'd94:  R_mul_77 = 16'd7238;
            8'd95:  R_mul_77 = 16'd7315;
            8'd96:  R_mul_77 = 16'd7392;
            8'd97:  R_mul_77 = 16'd7469;
            8'd98:  R_mul_77 = 16'd7546;
            8'd99:  R_mul_77 = 16'd7623;
            8'd100: R_mul_77 = 16'd7700;
            default: R_mul_77 = R * 77;  // For remaining values, but synthesizer will optimize
        endcase

        case (G)
            8'd0:   G_mul_150 = 16'd0;
            8'd1:   G_mul_150 = 16'd150;
            8'd2:   G_mul_150 = 16'd300;
            8'd3:   G_mul_150 = 16'd450;
            8'd4:   G_mul_150 = 16'd600;
            8'd5:   G_mul_150 = 16'd750;
            8'd6:   G_mul_150 = 16'd900;
            8'd7:   G_mul_150 = 16'd1050;
            8'd8:   G_mul_150 = 16'd1200;
            8'd9:   G_mul_150 = 16'd1350;
            8'd10:  G_mul_150 = 16'd1500;
            default: G_mul_150 = G * 150;
        endcase

        case (B)
            8'd0:   B_mul_29 = 16'd0;
            8'd1:   B_mul_29 = 16'd29;
            8'd2:   B_mul_29 = 16'd58;
            8'd3:   B_mul_29 = 16'd87;
            8'd4:   B_mul_29 = 16'd116;
            8'd5:   B_mul_29 = 16'd145;
            8'd6:   B_mul_29 = 16'd174;
            8'd7:   B_mul_29 = 16'd203;
            8'd8:   B_mul_29 = 16'd232;
            8'd9:   B_mul_29 = 16'd261;
            8'd10:  B_mul_29 = 16'd290;
            default: B_mul_29 = B * 29;
        endcase

        y_sum_stage1 = R_mul_77 + G_mul_150 + B_mul_29;
    end

    // Block 3: Cb Component Calculation (Sequential Pipeline Stage 1)
    logic [15:0] R_mul_43, G_mul_85, B_mul_128;
    logic [15:0] cb_sum_stage1;

    always_comb begin
        case (R)
            8'd0:   R_mul_43 = 16'd0;
            8'd1:   R_mul_43 = 16'd43;
            8'd2:   R_mul_43 = 16'd86;
            default: R_mul_43 = R * 43;
        endcase

        case (G)
            8'd0:   G_mul_85 = 16'd0;
            8'd1:   G_mul_85 = 16'd85;
            8'd2:   G_mul_85 = 16'd170;
            default: G_mul_85 = G * 85;
        endcase

        case (B)
            8'd0:   B_mul_128 = 16'd0;
            8'd1:   B_mul_128 = 16'd128;
            8'd2:   B_mul_128 = 16'd256;
            default: B_mul_128 = B * 128;
        endcase

        cb_sum_stage1 = B_mul_128 - R_mul_43 - G_mul_85 + 16'd32768;
    end

    // Block 4: Cr Component Calculation (Sequential Pipeline Stage 1)
    logic [15:0] R_mul_128, G_mul_107, B_mul_21;
    logic [15:0] cr_sum_stage1;

    always_comb begin
        case (R)
            8'd0:   R_mul_128 = 16'd0;
            8'd1:   R_mul_128 = 16'd128;
            8'd2:   R_mul_128 = 16'd256;
            default: R_mul_128 = R * 128;
        endcase

        case (G)
            8'd0:   G_mul_107 = 16'd0;
            8'd1:   G_mul_107 = 16'd107;
            8'd2:   G_mul_107 = 16'd214;
            default: G_mul_107 = G * 107;
        endcase

        case (B)
            8'd0:   B_mul_21 = 16'd0;
            8'd1:   B_mul_21 = 16'd21;
            8'd2:   B_mul_21 = 16'd42;
            default: B_mul_21 = B * 21;
        endcase

        cr_sum_stage1 = R_mul_128 - G_mul_107 - B_mul_21 + 16'd32768;
    end

    // Block 5: Pipeline Registers (Sequential)
    logic [15:0] y_sum_reg, cb_sum_reg, cr_sum_reg;
    logic        pixel_valid_reg;

    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                y_sum_reg <= 16'd0;
                cb_sum_reg <= 16'd0;
                cr_sum_reg <= 16'd0;
                pixel_valid_reg <= 1'b0;
            end
            1'b1: begin
                case (pixel_valid)
                    1'b1: begin
                        y_sum_reg <= y_sum_stage1;
                        cb_sum_reg <= cb_sum_stage1;
                        cr_sum_reg <= cr_sum_stage1;
                        pixel_valid_reg <= 1'b1;
                    end
                    default: begin
                        y_sum_reg <= y_sum_reg;
                        cb_sum_reg <= cb_sum_reg;
                        cr_sum_reg <= cr_sum_reg;
                        pixel_valid_reg <= 1'b0;
                    end
                endcase
            end
        endcase
    end

    // Block 6: Final Shift and Clipping (Combinational)
    logic [9:0] Y_out, Cb_out, Cr_out;

    always_comb begin
        // Y = (y_sum_reg >> 8), clip to 10-bit range
        case (y_sum_reg[15:8])
            8'd0:   Y_out = 10'd0;
            8'd1:   Y_out = 10'd1;
            8'd2:   Y_out = 10'd2;
            8'd3:   Y_out = 10'd3;
            8'd4:   Y_out = 10'd4;
            8'd5:   Y_out = 10'd5;
            8'd6:   Y_out = 10'd6;
            8'd7:   Y_out = 10'd7;
            8'd8:   Y_out = 10'd8;
            8'd9:   Y_out = 10'd9;
            8'd10:  Y_out = 10'd10;
            default: begin
                case (y_sum_reg[15:8] < 8'd255)
                    1'b1: Y_out = {2'b0, y_sum_reg[15:8]};
                    default: Y_out = 10'd255;
                endcase
            end
        endcase

        // Cb = (cb_sum_reg >> 8), clip to 10-bit range
        case (cb_sum_reg[15:8])
            8'd0:   Cb_out = 10'd0;
            default: begin
                case (cb_sum_reg[15:8] < 8'd255)
                    1'b1: Cb_out = {2'b0, cb_sum_reg[15:8]};
                    default: Cb_out = 10'd255;
                endcase
            end
        endcase

        // Cr = (cr_sum_reg >> 8), clip to 10-bit range
        case (cr_sum_reg[15:8])
            8'd0:   Cr_out = 10'd0;
            default: begin
                case (cr_sum_reg[15:8] < 8'd255)
                    1'b1: Cr_out = {2'b0, cr_sum_reg[15:8]};
                    default: Cr_out = 10'd255;
                endcase
            end
        endcase
    end

    // Block 7: Pixel Assembly
    always_comb begin
        ycbcr_pixel = {Y_out, Cb_out, Cr_out};
    end

    // Block 8: Video Timing Generator (720p @ 60Hz)
    // Horizontal: 1280 active, 110 front porch, 40 sync, 220 back porch (total 1650)
    // Vertical:   720 active, 5 front porch, 5 sync, 20 back porch (total 750)
    logic [10:0] h_counter;  // 0-1649
    logic [9:0]  v_counter;  // 0-749

    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                h_counter <= 11'd0;
                v_counter <= 10'd0;
            end
            1'b1: begin
                case (h_counter)
                    11'd1649: begin
                        h_counter <= 11'd0;
                        case (v_counter)
                            10'd749: v_counter <= 10'd0;
                            default: v_counter <= v_counter + 10'd1;
                        endcase
                    end
                    default: h_counter <= h_counter + 11'd1;
                endcase
            end
        endcase
    end

    // Block 9: Sync and Blanking Generation
    always_comb begin
        // Horizontal sync (40 pixels wide starting at 1380)
        case (h_counter)
            11'd1380, 11'd1381, 11'd1382, 11'd1383, 11'd1384, 11'd1385, 11'd1386, 11'd1387,
            11'd1388, 11'd1389, 11'd1390, 11'd1391, 11'd1392, 11'd1393, 11'd1394, 11'd1395,
            11'd1396, 11'd1397, 11'd1398, 11'd1399, 11'd1400, 11'd1401, 11'd1402, 11'd1403,
            11'd1404, 11'd1405, 11'd1406, 11'd1407, 11'd1408, 11'd1409, 11'd1410, 11'd1411,
            11'd1412, 11'd1413, 11'd1414, 11'd1415, 11'd1416, 11'd1417, 11'd1418, 11'd1419:
                h_sync = 10'b0;
            default: h_sync = 10'b1111111111;
        endcase

        // Vertical sync (5 lines starting at 725)
        case (v_counter)
            10'd725, 10'd726, 10'd727, 10'd728, 10'd729:
                v_sync = 10'b0;
            default: v_sync = 10'b1111111111;
        endcase

        // Horizontal blank (active pixels are 0-1279)
        case (h_counter < 11'd1280)
            1'b1: h_blank = 1'b0;
            default: h_blank = 1'b1;
        endcase

        // Vertical blank (active lines are 0-719)
        case (v_counter < 10'd720)
            1'b1: v_blank = 1'b0;
            default: v_blank = 1'b1;
        endcase
    end

endmodule,"The given code is a SystemVerilog module for an RGB to YCrCb color space converter. The module includes several blocks of code that perform different tasks such as color conversion, video timing generation and sync/blanking signal generation.

//=============================================================================
// ATM Transaction Controller
//
// Industry Theme: Financial Transaction State Machine
// - Uses only 'case' and 'casez' statements (no if/else)
// - 4 procedural blocks: 2 always_ff (sequential), 2 always_comb (combinational)
// - Implements card insertion, PIN verification, withdrawal, and balance inquiry
//=============================================================================

module atm_controller (
    // Clock and reset
    input  logic clk,
    input  logic rst_n,

    // Card interface
    input  logic card_inserted,
    input  logic [3:0] card_type,      // 4'b0001: debit, 4'b0010: credit, 4'b0100: prepaid

    // PIN pad interface
    input  logic [3:0] pin_entered,
    input  logic pin_enter_valid,

    // User selection (from touchscreen)
    input  logic [1:0] menu_select,    // 00: withdraw, 01: balance, 10: deposit, 11: exit

    // Amount entry
    input  logic [7:0] withdraw_amount,
    input  logic amount_valid,

    // Backend banking system interface
    input  logic [15:0] account_balance,
    input  logic pin_verified,
    input  logic transaction_approved,

    // Outputs
    output logic [7:0]  dispense_amount,
    output logic [15:0] new_balance,
    output logic [3:0]  transaction_status,  // 4-bit encoded status
    output logic        dispense_enable,
    output logic        card_eject,
    output logic        receipt_print
);

    //=========================================================================
    // State and Register Declarations
    //=========================================================================
    typedef enum logic [2:0] {
        IDLE,
        VERIFY_PIN,
        SELECT_TRANSACTION,
        PROCESS_WITHDRAWAL,
        PROCESS_BALANCE,
        COMPLETE,
        ERROR
    } state_t;

    state_t current_state, next_state;

    // Internal registers for transaction data
    logic [7:0]  pending_withdraw;
    logic [15:0] updated_balance;
    logic [3:0]  transaction_code;
    logic        card_valid;

    //=========================================================================
    // Block 1: Sequential State Register (always_ff with case)
    //=========================================================================
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: current_state <= IDLE;
            1'b1: current_state <= next_state;
        endcase
    end

    //=========================================================================
    // Block 2: Combinational Next State Logic (always_comb with casez)
    //=========================================================================
    always_comb begin
        next_state = current_state;  // Default to current

        casez (current_state)
            IDLE: begin
                casez ({card_inserted, card_type})
                    5'b1_0001: next_state = VERIFY_PIN;  // Debit card
                    5'b1_0010: next_state = VERIFY_PIN;  // Credit card
                    5'b1_0100: next_state = ERROR;       // Prepaid card not accepted
                    5'b0_????: next_state = IDLE;
                    default:   next_state = ERROR;
                endcase
            end

            VERIFY_PIN: begin
                casez ({pin_enter_valid, pin_verified})
                    2'b11: next_state = SELECT_TRANSACTION;
                    2'b10: next_state = ERROR;
                    2'b0?: next_state = VERIFY_PIN;
                    default: next_state = ERROR;
                endcase
            end

            SELECT_TRANSACTION: begin
                casez (menu_select)
                    2'b00: next_state = PROCESS_WITHDRAWAL;
                    2'b01: next_state = PROCESS_BALANCE;
                    2'b10: next_state = ERROR;      // Deposit not supported in this ATM
                    2'b11: next_state = COMPLETE;
                    default: next_state = SELECT_TRANSACTION;
                endcase
            end

            PROCESS_WITHDRAWAL: begin
                casez ({amount_valid, transaction_approved})
                    2'b11: next_state = COMPLETE;
                    2'b10: next_state = ERROR;
                    2'b0?: next_state = PROCESS_WITHDRAWAL;
                    default: next_state = ERROR;
                endcase
            end

            PROCESS_BALANCE: begin
                casez (transaction_approved)
                    1'b1: next_state = COMPLETE;
                    1'b0: next_state = ERROR;
                    default: next_state = PROCESS_BALANCE;
                endcase
            end

            COMPLETE: begin
                casez (card_inserted)
                    1'b1: next_state = COMPLETE;  // Wait for card removal
                    1'b0: next_state = IDLE;
                    default: next_state = COMPLETE;
                endcase
            end

            ERROR: begin
                casez (card_inserted)
                    1'b1: next_state = ERROR;     // Wait for card removal in error state
                    1'b0: next_state = IDLE;
                    default: next_state = ERROR;
                endcase
            end

            default: next_state = IDLE;
        endcase
    end
    //=========================================================================
    // Block 3: Sequential Transaction Processing (always_ff with case)
    //=========================================================================
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                pending_withdraw <= 8'd0;
                updated_balance <= 16'd0;
                transaction_code <= 4'd0;
                card_valid <= 1'b0;
            end
            1'b1: begin
                case (current_state)
                    IDLE: begin
                        case (card_inserted)
                            1'b1: card_valid <= 1'b1;
                            1'b0: card_valid <= 1'b0;
                        endcase
                    end

                    VERIFY_PIN: begin
                        transaction_code <= 4'd1;  // PIN verification transaction
                    end

                    SELECT_TRANSACTION: begin
                        case (menu_select)
                            2'b00: transaction_code <= 4'd2;  // Withdrawal
                            2'b01: transaction_code <= 4'd3;  // Balance inquiry
                            2'b10: transaction_code <= 4'd4;  // Deposit (error case)
                            2'b11: transaction_code <= 4'd5;  // Exit
                        endcase
                    end

                    PROCESS_WITHDRAWAL: begin
                        case (amount_valid)
                            1'b1: pending_withdraw <= withdraw_amount;
                            default: ;
                        endcase

                        case (transaction_approved)
                            1'b1: updated_balance <= account_balance - pending_withdraw;
                            default: updated_balance <= account_balance;
                        endcase
                    end

                    PROCESS_BALANCE: begin
                        updated_balance <= account_balance;
                    end

                    COMPLETE: begin
                        case (menu_select)
                            2'b00: pending_withdraw <= 8'd0;  // Clear after completion
                            default: ;
                        endcase
                    end

                    ERROR: begin
                        transaction_code <= 4'd15;  // Error code
                        pending_withdraw <= 8'd0;
                    end
                endcase
            end
        endcase
    end

    //=========================================================================
    // Block 4: Combinational Output Logic (always_comb with case)
    //=========================================================================
    always_comb begin
        // Default assignments
        dispense_amount = 8'd0;
        new_balance = account_balance;
        transaction_status = 4'd0;
        dispense_enable = 1'b0;
        card_eject = 1'b0;
        receipt_print = 1'b0;

        case (current_state)
            IDLE: begin
                transaction_status = 4'd0;  // Ready
                card_eject = 1'b0;
            end

            VERIFY_PIN: begin
                transaction_status = 4'd1;  // Verifying
            end

            SELECT_TRANSACTION: begin
                transaction_status = 4'd2;  // Awaiting selection
            end

            PROCESS_WITHDRAWAL: begin
                case (transaction_approved)
                    1'b1: begin
                        transaction_status = 4'd3;  // Processing
                        dispense_amount = pending_withdraw;
                        new_balance = updated_balance;
                    end
                    default: transaction_status = 4'd4;  // Pending approval
                endcase
            end

            PROCESS_BALANCE: begin
                transaction_status = 4'd5;  // Retrieving balance
                new_balance = updated_balance;
            end

            COMPLETE: begin
                case (menu_select)
                    2'b00: begin  // Withdrawal completed
                        dispense_enable = 1'b1;
                        receipt_print = 1'b1;
                        transaction_status = 4'd6;  // Success - dispense
                        new_balance = updated_balance;
                    end
                    2'b01: begin  // Balance inquiry completed
                        receipt_print = 1'b1;
                        transaction_status = 4'd7;  // Success - balance shown
                        new_balance = updated_balance;
                    end
                    2'b11: begin  // Exit
                        card_eject = 1'b1;
                        transaction_status = 4'd8;  // Complete - card ejected
                    end
                    default: begin
                        transaction_status = 4'd9;  // Complete - other
                        card_eject = 1'b1;
                    end
                endcase
            end

            ERROR: begin
                case (transaction_code)
                    4'd1: transaction_status = 4'd10;  // PIN error
                    4'd2: transaction_status = 4'd11;  // Withdrawal error
                    4'd3: transaction_status = 4'd12;  // Balance error
                    4'd4: transaction_status = 4'd13;  // Deposit error
                    4'd15: transaction_status = 4'd14; // General error
                    default: transaction_status = 4'd15; // Unknown error
                endcase
                card_eject = 1'b1;
                dispense_amount = 8'd0;
            end
        endcase

        // Override for card removal during error or complete
        casez ({current_state, card_inserted})
            {ERROR, 1'b0}: card_eject = 1'b0;
            {COMPLETE, 1'b0}: card_eject = 1'b0;
            default: ;
        endcase
    end

endmodule,"module atm_controller_assertions(

module memory_controller #(
    parameter ADDR_WIDTH = 16,
    parameter DATA_WIDTH = 32,
    parameter ECC_WIDTH = 7,  // Hamming code for 32-bit data
    parameter NUM_MASTERS = 4
) (
    // Clock and reset
    input  logic clk,
    input  logic rst_n,

    // Master interfaces
    input  logic [NUM_MASTERS-1:0]        master_req,
    input  logic [NUM_MASTERS-1:0][ADDR_WIDTH-1:0] master_addr,
    input  logic [NUM_MASTERS-1:0]        master_rw,  // 1=write, 0=read
    input  logic [NUM_MASTERS-1:0][DATA_WIDTH-1:0] master_wdata,
    output logic [NUM_MASTERS-1:0]        master_grant,
    output logic [NUM_MASTERS-1:0][DATA_WIDTH-1:0] master_rdata,
    output logic [NUM_MASTERS-1:0]        master_ack,

    // Memory interface
    output logic                          mem_cs,
    output logic                          mem_we,
    output logic [ADDR_WIDTH-1:0]         mem_addr,
    output logic [DATA_WIDTH+ECC_WIDTH-1:0] mem_wdata,
    input  logic [DATA_WIDTH+ECC_WIDTH-1:0] mem_rdata,
    input  logic                          mem_rdy
);

    // Internal state
    typedef enum logic [2:0] {
        IDLE         = 3'b000,
        ARB_WAIT     = 3'b001,
        CMD_SEND     = 3'b010,
        DATA_WAIT    = 3'b011,
        DATA_CAPTURE = 3'b100,
        ECC_CHECK    = 3'b101,
        RESPONSE     = 3'b110
    } state_t;

    state_t current_state, next_state;

    // Arbitration and request tracking
    logic [NUM_MASTERS-1:0] req_latched;
    logic [NUM_MASTERS-1:0] req_priority;
    logic [NUM_MASTERS-1:0] grant_current;
    logic [ADDR_WIDTH-1:0]  active_addr;
    logic                   active_rw;
    logic [DATA_WIDTH-1:0]  active_wdata;
    logic [NUM_MASTERS-1:0] active_master;
    logic [DATA_WIDTH+ECC_WIDTH-1:0] ecc_encoded_data;
    logic [DATA_WIDTH+ECC_WIDTH-1:0] ecc_decoded_data;
    logic [ECC_WIDTH-1:0]   ecc_syndrome;
    logic                   ecc_error;
    logic                   ecc_corrected;

    // Counter for timing
    logic [2:0] wait_counter;
    logic [2:0] wait_target;

    // Pipeline registers
    logic [DATA_WIDTH-1:0] response_data;
    logic [NUM_MASTERS-1:0] response_master;
    logic response_valid;

    //------------------------------------------------------------------------
    // Block 1: Request Latching (Sequential)
    //------------------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: req_latched <= '0;
            1'b1: begin
                case (current_state)
                    IDLE: req_latched <= master_req;
                    CMD_SEND: begin
                        case (mem_rdy)
                            1'b1: req_latched <= req_latched & ~grant_current;
                            default: req_latched <= req_latched;
                        endcase
                    end
                    default: req_latched <= req_latched;
                endcase
            end
        endcase
    end

    //------------------------------------------------------------------------
    // Block 2: Priority Encoder (Combinational - Case Only)
    //------------------------------------------------------------------------
    always_comb begin
        req_priority = 4'b0000;

        // Fixed priority: Master 0 > Master 1 > Master 2 > Master 3
        casez (req_latched)
            4'b???1: req_priority = 4'b0001;
            4'b??10: req_priority = 4'b0010;
            4'b?100: req_priority = 4'b0100;
            4'b1000: req_priority = 4'b1000;
            default: req_priority = 4'b0000;
        endcase
    end

    //------------------------------------------------------------------------
    // Block 3: State Transition Logic (Combinational - Case Only)
    //------------------------------------------------------------------------
    always_comb begin
        next_state = current_state;

        case (current_state)
            IDLE: begin
                case (|req_latched)
                    1'b1: next_state = ARB_WAIT;
                    default: next_state = IDLE;
                endcase
            end

            ARB_WAIT: begin
                case (req_priority != 4'b0000)
                    1'b1: next_state = CMD_SEND;
                    default: next_state = ARB_WAIT;
                endcase
            end

            CMD_SEND: begin
                case (mem_rdy)
                    1'b1: begin
                        case (active_rw)
                            1'b1: next_state = DATA_WAIT;
                            default: next_state = DATA_CAPTURE;
                        endcase
                    end
                    default: next_state = CMD_SEND;
                endcase
            end

            DATA_WAIT: begin
                case (wait_counter == wait_target)
                    1'b1: next_state = DATA_CAPTURE;
                    default: next_state = DATA_WAIT;
                endcase
            end

            DATA_CAPTURE: begin
                case (mem_rdy)
                    1'b1: begin
                        case (active_rw)
                            1'b1: next_state = RESPONSE;
                            default: next_state = ECC_CHECK;
                        endcase
                    end
                    default: next_state = DATA_CAPTURE;
                endcase
            end

            ECC_CHECK: begin
                next_state = RESPONSE;
            end

            RESPONSE: begin
                next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

    //------------------------------------------------------------------------
    // Block 4: Main State Machine and Grant Logic (Sequential - Single Block)
    //------------------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                current_state <= IDLE;
                grant_current <= '0;
                active_master <= '0;
                active_addr <= '0;
                active_rw <= 1'b0;
                active_wdata <= '0;
                wait_counter <= 3'b0;
                wait_target <= 3'b0;
                response_data <= '0;
                response_master <= '0;
                response_valid <= 1'b0;
            end
            1'b1: begin
                current_state <= next_state;

                case (current_state)
                    IDLE: begin
                        grant_current <= '0;
                        response_valid <= 1'b0;
                        wait_counter <= 3'b0;
                    end

                    ARB_WAIT: begin
                        case (req_priority != 4'b0000)
                            1'b1: begin
                                grant_current <= req_priority;

                                // Capture active request details
                                case (req_priority)
                                    4'b0001: begin
                                        active_master <= 4'b0001;
                                        active_addr <= master_addr[0];
                                        active_rw <= master_rw[0];
                                        active_wdata <= master_wdata[0];
                                    end
                                    4'b0010: begin
                                        active_master <= 4'b0010;
                                        active_addr <= master_addr[1];
                                        active_rw <= master_rw[1];
                                        active_wdata <= master_wdata[1];
                                    end
                                    4'b0100: begin
                                        active_master <= 4'b0100;
                                        active_addr <= master_addr[2];
                                        active_rw <= master_rw[2];
                                        active_wdata <= master_wdata[2];
                                    end
                                    4'b1000: begin
                                        active_master <= 4'b1000;
                                        active_addr <= master_addr[3];
                                        active_rw <= master_rw[3];
                                        active_wdata <= master_wdata[3];
                                    end
                                    default: begin
                                        active_master <= active_master;
                                        active_addr <= active_addr;
                                        active_rw <= active_rw;
                                        active_wdata <= active_wdata;
                                    end
                                endcase
                            end
                            default: begin
                                grant_current <= grant_current;
                                active_master <= active_master;
                                active_addr <= active_addr;
                                active_rw <= active_rw;
                                active_wdata <= active_wdata;
                            end
                        endcase
                    end

                    CMD_SEND: begin
                        case (mem_rdy)
                            1'b1: begin
                                wait_counter <= 3'b0;
                                case (active_rw)
                                    1'b1: wait_target <= 3'd3;
                                    default: wait_target <= 3'd2;
                                endcase
                            end
                            default: begin
                                wait_counter <= wait_counter;
                                wait_target <= wait_target;
                            end
                        endcase
                    end

                    DATA_WAIT: begin
                        wait_counter <= wait_counter + 1'b1;
                    end

                    DATA_CAPTURE: begin
                        case (mem_rdy)
                            1'b1: begin
                                case (active_rw)
                                    1'b0: begin
                                        response_data <= ecc_decoded_data[DATA_WIDTH-1:0];
                                        response_master <= active_master;
                                        response_valid <= 1'b1;
                                    end
                                    default: begin
                                        response_data <= response_data;
                                        response_master <= response_master;
                                        response_valid <= response_valid;
                                    end
                                endcase
                            end
                            default: begin
                                response_data <= response_data;
                                response_master <= response_master;
                                response_valid <= response_valid;
                            end
                        endcase
                    end

                    RESPONSE: begin
                        // Hold values during response
                    end

                    default: begin
                        // Hold all values
                    end
                endcase
            end
        endcase
    end

    //------------------------------------------------------------------------
    // Block 5: ECC Encoding for Write Data (Sequential - Falling Edge)
    //------------------------------------------------------------------------
    always_ff @(negedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: ecc_encoded_data <= '0;
            1'b1: begin
                case (current_state)
                    CMD_SEND: begin
                        case (active_rw)
                            1'b1: begin
                                // Generate Hamming code for 32-bit data
                                ecc_encoded_data[DATA_WIDTH-1:0] <= active_wdata;
                                ecc_encoded_data[DATA_WIDTH +: ECC_WIDTH] <= {
                                    ^(active_wdata & 32'hAAAAAAAA),  // Even parity for bit0
                                    ^(active_wdata & 32'hCCCCCCCC),  // Even parity for bit1
                                    ^(active_wdata & 32'hF0F0F0F0),  // Even parity for bit2
                                    ^(active_wdata & 32'hFF00FF00),  // Even parity for bit3
                                    ^(active_wdata & 32'hFFFF0000),  // Even parity for bit4
                                    ^(active_wdata & 32'hFFFFFFFF),  // Overall parity
                                    ^(active_wdata & 32'hF0F0F0F0) ^ ^(active_wdata & 32'h0F0F0F0F)
                                };
                            end
                            default: ecc_encoded_data <= ecc_encoded_data;
                        endcase
                    end
                    default: ecc_encoded_data <= ecc_encoded_data;
                endcase
            end
        endcase
    end

    //------------------------------------------------------------------------
    // Block 6: ECC Decoding and Error Detection (Combinational - Case Only)
    //------------------------------------------------------------------------
    always_comb begin
        ecc_syndrome = '0;
        ecc_error = 1'b0;
        ecc_corrected = 1'b0;
        ecc_decoded_data = mem_rdata;

        // Calculate syndrome bits using case
        case (1'b1)
            1'b1: begin
                ecc_syndrome[0] = ^mem_rdata[31:0] ^ mem_rdata[32];
                ecc_syndrome[1] = ^(mem_rdata[31:0] & 32'hAAAAAAAA) ^ mem_rdata[33];
                ecc_syndrome[2] = ^(mem_rdata[31:0] & 32'hCCCCCCCC) ^ mem_rdata[34];
                ecc_syndrome[3] = ^(mem_rdata[31:0] & 32'hF0F0F0F0) ^ mem_rdata[35];
                ecc_syndrome[4] = ^(mem_rdata[31:0] & 32'hFF00FF00) ^ mem_rdata[36];
                ecc_syndrome[5] = ^(mem_rdata[31:0] & 32'hFFFF0000) ^ mem_rdata[37];
                ecc_syndrome[6] = ^mem_rdata ^ mem_rdata[38];
            end
        endcase

        // Error detection
        case (ecc_syndrome != 7'b0)
            1'b1: ecc_error = 1'b1;
            default: ecc_error = 1'b0;
        endcase

        // Error correction based on syndrome
        case (ecc_syndrome)
            7'b0000001: begin
                ecc_corrected = 1'b1;
                ecc_decoded_data[0] = ~mem_rdata[0];
            end
            7'b0000010: begin
                ecc_corrected = 1'b1;
                ecc_decoded_data[1] = ~mem_rdata[1];
            end
            7'b0000100: begin
                ecc_corrected = 1'b1;
                ecc_decoded_data[2] = ~mem_rdata[2];
            end
            7'b0001000: begin
                ecc_corrected = 1'b1;
                ecc_decoded_data[3] = ~mem_rdata[3];
            end
            7'b0010000: begin
                ecc_corrected = 1'b1;
                ecc_decoded_data[4] = ~mem_rdata[4];
            end
            7'b0100000: begin
                ecc_corrected = 1'b1;
                ecc_decoded_data[5] = ~mem_rdata[5];
            end
            7'b1000000: begin
                ecc_corrected = 1'b1;
                ecc_decoded_data[6] = ~mem_rdata[6];
            end
            default: begin
                ecc_corrected = 1'b0;
                ecc_decoded_data = ecc_decoded_data;
            end
        endcase
    end

    //------------------------------------------------------------------------
    // Block 7: Output Assignments (Combinational - Case Only)
    //------------------------------------------------------------------------
    always_comb begin
        // Default assignments
        master_grant = 4'b0000;
        master_ack = 4'b0000;
        master_rdata = '{default: '0};
        mem_cs = 1'b0;
        mem_we = 1'b0;
        mem_addr = '0;
        mem_wdata = '0;

        case (current_state)
            ARB_WAIT: begin
                master_grant = req_priority;
            end

            CMD_SEND: begin
                case (mem_rdy)
                    1'b1: begin
                        mem_cs = 1'b1;
                        mem_we = active_rw;
                        mem_addr = active_addr;
                        case (active_rw)
                            1'b1: mem_wdata = ecc_encoded_data;
                            default: mem_wdata = '0;
                        endcase
                    end
                    default: begin
                        mem_cs = 1'b0;
                        mem_we = 1'b0;
                    end
                endcase
            end

            DATA_CAPTURE: begin
                case (mem_rdy)
                    1'b1: begin
                        mem_cs = 1'b1;
                        mem_we = active_rw;
                        mem_addr = active_addr;
                    end
                    default: begin
                        mem_cs = 1'b0;
                        mem_we = 1'b0;
                    end
                endcase
            end

            RESPONSE: begin
                case (response_master)
                    4'b0001: begin
                        master_rdata[0] = response_data;
                        master_ack = 4'b0001;
                    end
                    4'b0010: begin
                        master_rdata[1] = response_data;
                        master_ack = 4'b0010;
                    end
                    4'b0100: begin
                        master_rdata[2] = response_data;
                        master_ack = 4'b0100;
                    end
                    4'b1000: begin
                        master_rdata[3] = response_data;
                        master_ack = 4'b1000;
                    end
                    default: begin
                        master_rdata = '{default: '0};
                        master_ack = 4'b0000;
                    end
                endcase
            end

            default: begin
                master_grant = 4'b0000;
                master_ack = 4'b0000;
                master_rdata = '{default: '0};
                mem_cs = 1'b0;
                mem_we = 1'b0;
            end
        endcase
    end

endmodule,"module memory_controller (

module fifo #(
    parameter DEPTH = 16,           // Number of entries
    parameter DATA_WIDTH = 8,       // Width of data
    parameter ALMOST_THRESHOLD = 4  // Almost full/empty margin
) (
    input logic clk,
    input logic rst_n,
    input logic wr_en,
    input logic rd_en,
    input logic [DATA_WIDTH-1:0] wr_data,
    output logic [DATA_WIDTH-1:0] rd_data,
    output logic full,
    output logic empty,
    output logic almost_full,
    output logic almost_empty
);

    // Local parameters for pointer widths
    localparam PTR_WIDTH = $clog2(DEPTH);
    localparam PTR_MAX   = DEPTH - 1;

    // ------------------------------------------------------------
    // 1. Sequential Block: Pointer Logic
    // ------------------------------------------------------------
    logic [PTR_WIDTH-1:0] wr_ptr, rd_ptr;
    logic [PTR_WIDTH-1:0] wr_ptr_next, rd_ptr_next;
    logic                  wr_ptr_en, rd_ptr_en;

    // Write pointer sequential logic
    always_ff @(posedge clk or negedge rst_n) begin
        case ({rst_n, wr_ptr_en})
            2'b0?: wr_ptr <= '0;                    // Reset when rst_n is 0
            2'b11: wr_ptr <= wr_ptr_next;           // Enable when rst_n=1 and wr_ptr_en=1
            default: wr_ptr <= wr_ptr;              // Hold otherwise
        endcase
    end

    // Read pointer sequential logic
    always_ff @(posedge clk or negedge rst_n) begin
        case ({rst_n, rd_ptr_en})
            2'b0?: rd_ptr <= '0;                    // Reset when rst_n is 0
            2'b11: rd_ptr <= rd_ptr_next;           // Enable when rst_n=1 and rd_ptr_en=1
            default: rd_ptr <= rd_ptr;              // Hold otherwise
        endcase
    end

    // ------------------------------------------------------------
    // 2. Combinational Block: Status Calculation
    // ------------------------------------------------------------
    logic [PTR_WIDTH:0]  count;           // Current fill level (1 extra bit)
    logic [PTR_WIDTH-1:0] wr_ptr_comb, rd_ptr_comb;
    logic                 full_comb, empty_comb;
    logic                 almost_full_comb, almost_empty_comb;
    logic                 wr_enable, rd_enable;

    // Calculate current fill level using difference between pointers
    always_comb begin
        // Default assignments
        wr_ptr_comb = wr_ptr;
        rd_ptr_comb = rd_ptr;

        // Determine count based on pointer relationship
        case (1'b1)  // Using case for conditional logic
            (wr_ptr == rd_ptr): begin
                count = '0;
            end
            (wr_ptr > rd_ptr): begin
                // No wrap: count = wr_ptr - rd_ptr
                count = wr_ptr - rd_ptr;
            end
            (wr_ptr < rd_ptr): begin
                // Wrap occurred: count = (DEPTH - rd_ptr) + wr_ptr
                count = (PTR_MAX - rd_ptr) + wr_ptr + 1;
            end
            default: begin
                count = '0;
            end
        endcase
    end

    // Generate status flags using case statements
    always_comb begin
        // Empty flag
        case (count)
            0: empty_comb = 1'b1;
            default: empty_comb = 1'b0;
        endcase

        // Full flag
        case (count)
            DEPTH: full_comb = 1'b1;
            default: full_comb = 1'b0;
        endcase

        // Almost empty flag
        case (1'b1)
            ((count <= ALMOST_THRESHOLD) && (count != 0)): almost_empty_comb = 1'b1;
            default: almost_empty_comb = 1'b0;
        endcase

        // Almost full flag
        case (1'b1)
            ((count >= (DEPTH - ALMOST_THRESHOLD)) && (count != DEPTH)): almost_full_comb = 1'b1;
            default: almost_full_comb = 1'b0;
        endcase
    end

    // Generate enable signals with case statements
    always_comb begin
        // Write enable logic
        case ({wr_en, full_comb})
            2'b10: wr_enable = 1'b1;
            default: wr_enable = 1'b0;
        endcase

        // Read enable logic
        case ({rd_en, empty_comb})
            2'b10: rd_enable = 1'b1;
            default: rd_enable = 1'b0;
        endcase
    end

    // Assign pointer enables
    assign wr_ptr_en = wr_enable;
    assign rd_ptr_en = rd_enable;

    // Assign status outputs
    assign empty = empty_comb;
    assign full = full_comb;
    assign almost_empty = almost_empty_comb;
    assign almost_full = almost_full_comb;

    // ------------------------------------------------------------
    // 3. Combinational Block: Next Pointer Calculation
    // ------------------------------------------------------------
    always_comb begin
        // Default: stay at current value
        wr_ptr_next = wr_ptr;
        rd_ptr_next = rd_ptr;

        // Write pointer next state using case
        case (wr_ptr_en)
            1'b1: begin
                case (wr_ptr)
                    PTR_MAX: wr_ptr_next = '0;
                    default: wr_ptr_next = wr_ptr + 1;
                endcase
            end
            default: wr_ptr_next = wr_ptr;
        endcase

        // Read pointer next state using case
        case (rd_ptr_en)
            1'b1: begin
                case (rd_ptr)
                    PTR_MAX: rd_ptr_next = '0;
                    default: rd_ptr_next = rd_ptr + 1;
                endcase
            end
            default: rd_ptr_next = rd_ptr;
        endcase
    end

    // ------------------------------------------------------------
    // 4. Sequential Block: Memory Array
    // ------------------------------------------------------------
    logic [DATA_WIDTH-1:0] mem [0:DEPTH-1];

    // Write operation
    always_ff @(posedge clk) begin
        case (wr_enable)
            1'b1: mem[wr_ptr] <= wr_data;
            default: ;
        endcase
    end

    // ------------------------------------------------------------
    // 5. Output Logic: Read Data Mux
    // ------------------------------------------------------------
    // Combinational read with case to select output
    always_comb begin
        // Use case to select output based on read pointer
        case (rd_ptr)
            default: rd_data = mem[rd_ptr];
        endcase
    end

endmodule,"module fifo #(

module jpeg_huffman_decoder (
    input  logic        clk,
    input  logic        rst_n,

    // Input bitstream interface
    input  logic        bitstream_valid,
    input  logic [31:0] bitstream_data,
    output logic        bitstream_ready,

    // Output decoded symbols
    output logic [7:0]  decoded_symbol,
    output logic        symbol_valid,
    output logic        end_of_block,

    // Configuration
    input  logic        select_dc_table,  // 0 = AC table, 1 = DC table
    input  logic [3:0]  reset_interval,   // Reset every N MCUs

    // Status
    output logic        huffman_error,
    output logic        table_overflow
);

    //------------------------------------------------------------------------
    // Block 1: Bitstream Buffer (Sequential)
    //------------------------------------------------------------------------
    logic [31:0] bit_buffer;
    logic [4:0]  bits_available;  // 0-32 bits available
    logic [4:0]  bits_consumed;

    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                bit_buffer <= 32'b0;
                bits_available <= 5'b0;
                bitstream_ready <= 1'b1;
            end
            1'b1: begin
                case (bitstream_valid)
                    1'b1: begin
                        case (bits_available < 5'd16)
                            1'b1: begin
                                bit_buffer <= {bit_buffer[15:0], bitstream_data[31:16]};
                                bits_available <= bits_available + 5'd16;
                                bitstream_ready <= 1'b1;
                            end
                            default: begin
                                bit_buffer <= bit_buffer;
                                bits_available <= bits_available;
                                bitstream_ready <= 1'b0;
                            end
                        endcase
                    end
                    default: begin
                        bit_buffer <= bit_buffer;
                        bits_available <= bits_available - bits_consumed;
                        bitstream_ready <= 1'b1;
                    end
                endcase
            end
        endcase
    end

    //------------------------------------------------------------------------
    // Block 2: Huffman Table Storage (Predefined Tables)
    // DC Luminance table (JPEG standard)
    //------------------------------------------------------------------------
    logic [15:0] dc_huff_val;
    logic [7:0]  dc_symbol;
    logic [3:0]  dc_code_len;

    // AC Luminance table (JPEG standard)
    logic [15:0] ac_huff_val;
    logic [7:0]  ac_symbol;
    logic [3:0]  ac_code_len;

    always_comb begin
        // Default values
        dc_huff_val = 16'b0;
        dc_symbol = 8'b0;
        dc_code_len = 4'b0;

        // DC Huffman table (simplified - actual table has 12 codes)
        case (bit_buffer[31:28])  // First 4 bits for DC lookup
            4'b0000: begin
                dc_huff_val = 16'h0001;
                dc_symbol = 8'h00;
                dc_code_len = 4'd2;
            end
            4'b0001: begin
                dc_huff_val = 16'h0002;
                dc_symbol = 8'h01;
                dc_code_len = 4'd3;
            end
            4'b0010: begin
                dc_huff_val = 16'h0003;
                dc_symbol = 8'h02;
                dc_code_len = 4'd3;
            end
            4'b0011: begin
                dc_huff_val = 16'h0004;
                dc_symbol = 8'h03;
                dc_code_len = 4'd3;
            end
            4'b0100: begin
                dc_huff_val = 16'h0005;
                dc_symbol = 8'h04;
                dc_code_len = 4'd3;
            end
            4'b0101: begin
                dc_huff_val = 16'h0006;
                dc_symbol = 8'h05;
                dc_code_len = 4'd3;
            end
            4'b0110: begin
                dc_huff_val = 16'h0007;
                dc_symbol = 8'h06;
                dc_code_len = 4'd4;
            end
            4'b0111: begin
                dc_huff_val = 16'h0008;
                dc_symbol = 8'h07;
                dc_code_len = 4'd5;
            end
            4'b1000: begin
                dc_huff_val = 16'h0009;
                dc_symbol = 8'h08;
                dc_code_len = 4'd6;
            end
            4'b1001: begin
                dc_huff_val = 16'h000A;
                dc_symbol = 8'h09;
                dc_code_len = 4'd7;
            end
            4'b1010: begin
                dc_huff_val = 16'h000B;
                dc_symbol = 8'h0A;
                dc_code_len = 4'd8;
            end
            4'b1011: begin
                dc_huff_val = 16'h000C;
                dc_symbol = 8'h0B;
                dc_code_len = 4'd9;
            end
            default: begin
                dc_huff_val = 16'h0000;
                dc_symbol = 8'hFF;  // EOB marker
                dc_code_len = 4'd0;
            end
        endcase
    end

    always_comb begin
        // Default values
        ac_huff_val = 16'b0;
        ac_symbol = 8'b0;
        ac_code_len = 4'b0;

        // AC Huffman table (simplified - first 16 codes)
        case (bit_buffer[31:24])  // First 8 bits for AC lookup
            8'b00000000: begin
                ac_huff_val = 16'h0001;
                ac_symbol = 8'h00;
                ac_code_len = 4'd4;
            end
            8'b00000001: begin
                ac_huff_val = 16'h0002;
                ac_symbol = 8'h01;
                ac_code_len = 4'd4;
            end
            8'b00000010: begin
                ac_huff_val = 16'h0003;
                ac_symbol = 8'h02;
                ac_code_len = 4'd5;
            end
            8'b00000011: begin
                ac_huff_val = 16'h0004;
                ac_symbol = 8'h03;
                ac_code_len = 4'd5;
            end
            8'b00000100: begin
                ac_huff_val = 16'h0005;
                ac_symbol = 8'h04;
                ac_code_len = 4'd6;
            end
            8'b00000101: begin
                ac_huff_val = 16'h0006;
                ac_symbol = 8'h05;
                ac_code_len = 4'd6;
            end
            8'b00000110: begin
                ac_huff_val = 16'h0007;
                ac_symbol = 8'h06;
                ac_code_len = 4'd7;
            end
            8'b00000111: begin
                ac_huff_val = 16'h0008;
                ac_symbol = 8'h07;
                ac_code_len = 4'd7;
            end
            8'b00001000: begin
                ac_huff_val = 16'h0009;
                ac_symbol = 8'h08;
                ac_code_len = 4'd8;
            end
            8'b00001001: begin
                ac_huff_val = 16'h000A;
                ac_symbol = 8'h09;
                ac_code_len = 4'd8;
            end
            8'b00001010: begin
                ac_huff_val = 16'h000B;
                ac_symbol = 8'h0A;
                ac_code_len = 4'd9;
            end
            8'b11111110: begin
                ac_huff_val = 16'hFFF0;
                ac_symbol = 8'hF0;  // ZRL (16 zeros)
                ac_code_len = 4'd12;
            end
            8'b11111111: begin
                ac_huff_val = 16'hFFF1;
                ac_symbol = 8'h00;  // EOB
                ac_code_len = 4'd4;
            end
            default: begin
                ac_huff_val = 16'h0000;
                ac_symbol = 8'h00;
                ac_code_len = 4'd0;
            end
        endcase
    end

    //------------------------------------------------------------------------
    // Block 3: Huffman Decoder State Machine
    //------------------------------------------------------------------------
    typedef enum logic [2:0] {
        IDLE,
        GET_CODE,
        DECODE,
        OUTPUT,
        ERROR
    } decode_state_t;

    decode_state_t current_state, next_state;
    logic [3:0]  code_length;
    logic [7:0]  decoded_sym;
    logic [3:0]  zero_run;
    logic [3:0]  value_bits;
    logic [15:0] decoded_value;

    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: current_state <= IDLE;
            1'b1: current_state <= next_state;
        endcase
    end

    // State transition logic
    always_comb begin
        next_state = current_state;

        case (current_state)
            IDLE: begin
                case (bitstream_valid && (bits_available >= 5'd8))
                    1'b1: next_state = GET_CODE;
                    default: next_state = IDLE;
                endcase
            end

            GET_CODE: begin
                case (select_dc_table)
                    1'b1: begin  // DC table
                        case (dc_code_len != 4'b0)
                            1'b1: next_state = DECODE;
                            default: next_state = ERROR;
                        endcase
                    end
                    1'b0: begin  // AC table
                        case (ac_code_len != 4'b0)
                            1'b1: next_state = DECODE;
                            default: next_state = ERROR;
                        endcase
                    end
                endcase
            end

            DECODE: begin
                case (select_dc_table)
                    1'b1: next_state = OUTPUT;
                    1'b0: begin
                        case (ac_symbol)
                            8'h00: begin  // EOB
                                next_state = OUTPUT;
                            end
                            8'hF0: begin  // ZRL
                                next_state = GET_CODE;
                            end
                            default: begin
                                case (zero_run != 4'b0)
                                    1'b1: next_state = OUTPUT;
                                    default: next_state = OUTPUT;
                                endcase
                            end
                        endcase
                    end
                endcase
            end

            OUTPUT: begin
                next_state = IDLE;
            end

            ERROR: begin
                case (bitstream_valid)
                    1'b1: next_state = IDLE;
                    default: next_state = ERROR;
                endcase
            end

            default: next_state = IDLE;
        endcase
    end

    //------------------------------------------------------------------------
    // Block 4: Decoder Control (Sequential)
    //------------------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                code_length <= 4'b0;
                decoded_sym <= 8'b0;
                zero_run <= 4'b0;
                value_bits <= 4'b0;
                bits_consumed <= 5'b0;
            end
            1'b1: begin
                case (current_state)
                    GET_CODE: begin
                        case (select_dc_table)
                            1'b1: begin  // DC
                                code_length <= dc_code_len;
                                decoded_sym <= dc_symbol;
                                bits_consumed <= {1'b0, dc_code_len};
                                zero_run <= 4'b0;
                                value_bits <= dc_symbol[3:0];
                            end
                            1'b0: begin  // AC
                                code_length <= ac_code_len;
                                decoded_sym <= ac_symbol;
                                bits_consumed <= {1'b0, ac_code_len};
                                case (ac_symbol)
                                    8'hF0: begin  // ZRL
                                        zero_run <= 4'd16;
                                        value_bits <= 4'b0;
                                    end
                                    8'h00: begin  // EOB
                                        zero_run <= 4'b0;
                                        value_bits <= 4'b0;
                                    end
                                    default: begin
                                        zero_run <= ac_symbol[7:4];
                                        value_bits <= ac_symbol[3:0];
                                    end
                                endcase
                            end
                        endcase
                    end

                    default: begin
                        code_length <= code_length;
                        decoded_sym <= decoded_sym;
                        zero_run <= zero_run;
                        value_bits <= value_bits;
                        bits_consumed <= bits_consumed;
                    end
                endcase
            end
        endcase
    end

    //------------------------------------------------------------------------
    // Block 5: Value Extraction (Combinational)
    //------------------------------------------------------------------------
    logic [15:0] extracted_value;

    always_comb begin
        extracted_value = 16'b0;

        case (value_bits)
            4'd0: extracted_value = 16'd0;
            4'd1: begin
                case (bit_buffer[code_length +: 1])
                    1'b1: extracted_value = 16'd1;
                    1'b0: extracted_value = -16'd1;
                endcase
            end
            4'd2: begin
                case (bit_buffer[code_length +: 2])
                    2'b11: extracted_value = 16'd3;
                    2'b10: extracted_value = 16'd2;
                    2'b01: extracted_value = -16'd1;
                    2'b00: extracted_value = -16'd2;
                endcase
            end
            4'd3: begin
                case (bit_buffer[code_length +: 3])
                    3'b111: extracted_value = 16'd7;
                    3'b110: extracted_value = 16'd6;
                    3'b101: extracted_value = 16'd5;
                    3'b100: extracted_value = 16'd4;
                    3'b011: extracted_value = -16'd1;
                    3'b010: extracted_value = -16'd2;
                    3'b001: extracted_value = -16'd3;
                    3'b000: extracted_value = -16'd4;
                endcase
            end
            4'd4: begin
                case (bit_buffer[code_length +: 4])
                    4'b1111: extracted_value = 16'd15;
                    4'b1110: extracted_value = 16'd14;
                    4'b1101: extracted_value = 16'd13;
                    4'b1100: extracted_value = 16'd12;
                    4'b1011: extracted_value = 16'd11;
                    4'b1010: extracted_value = 16'd10;
                    4'b1001: extracted_value = 16'd9;
                    4'b1000: extracted_value = 16'd8;
                    4'b0111: extracted_value = -16'd1;
                    4'b0110: extracted_value = -16'd2;
                    4'b0101: extracted_value = -16'd3;
                    4'b0100: extracted_value = -16'd4;
                    4'b0011: extracted_value = -16'd5;
                    4'b0010: extracted_value = -16'd6;
                    4'b0001: extracted_value = -16'd7;
                    4'b0000: extracted_value = -16'd8;
                endcase
            end
            default: extracted_value = 16'b0;
        endcase
    end

    //------------------------------------------------------------------------
    // Block 6: Run-Length Decoder (Sequential)
    //------------------------------------------------------------------------
    logic [3:0]  run_counter;
    logic [63:0] coeff_buffer [0:63];  // 8x8 block coefficients
    logic [5:0]  coeff_index;
    logic [5:0]  mcu_counter;

    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                run_counter <= 4'b0;
                coeff_index <= 6'b0;
                mcu_counter <= 6'b0;
                end_of_block <= 1'b0;
            end
            1'b1: begin
                case (current_state)
                    DECODE: begin
                        case (select_dc_table)
                            1'b1: begin  // DC
                                coeff_buffer[0] <= extracted_value;
                                coeff_index <= 6'd1;
                                run_counter <= 4'b0;
                                end_of_block <= 1'b0;
                            end
                            1'b0: begin  // AC
                                case (decoded_sym)
                                    8'h00: begin  // EOB
                                        coeff_index <= 6'd64;
                                        end_of_block <= 1'b1;
                                    end
                                    8'hF0: begin  // ZRL
                                        coeff_index <= coeff_index + 6'd16;
                                        run_counter <= 4'b0;
                                        end_of_block <= 1'b0;
                                    end
                                    default: begin
                                        coeff_index <= coeff_index + {2'b0, zero_run} + 6'd1;
                                        run_counter <= zero_run;
                                        end_of_block <= 1'b0;
                                    end
                                endcase
                            end
                        endcase
                    end

                    OUTPUT: begin
                        case (coeff_index >= 6'd64)
                            1'b1: begin
                                coeff_index <= 6'b0;
                                mcu_counter <= mcu_counter + 6'd1;
                            end
                            default: begin
                                coeff_index <= coeff_index;
                                mcu_counter <= mcu_counter;
                            end
                        endcase
                    end

                    default: begin
                        coeff_index <= coeff_index;
                        run_counter <= run_counter;
                        mcu_counter <= mcu_counter;
                        end_of_block <= 1'b0;
                    end
                endcase
            end
        endcase
    end

    //------------------------------------------------------------------------
    // Block 7: DC Predictor (Sequential with Reset)
    //------------------------------------------------------------------------
    logic [15:0] dc_predictor;
    logic [15:0] dc_output;

    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                dc_predictor <= 16'b0;
                dc_output <= 16'b0;
            end
            1'b1: begin
                case (current_state)
                    OUTPUT: begin
                        case (select_dc_table)
                            1'b1: begin  // DC
                                dc_output <= dc_predictor + extracted_value;
                                dc_predictor <= dc_predictor + extracted_value;

                                // Reset predictor at interval
                                case ((mcu_counter + 6'd1) % {2'b0, reset_interval} == 6'b0)
                                    1'b1: dc_predictor <= 16'b0;
                                    default: dc_predictor <= dc_predictor;
                                endcase
                            end
                            default: begin
                                dc_output <= dc_output;
                                dc_predictor <= dc_predictor;
                            end
                        endcase
                    end
                    default: begin
                        dc_output <= dc_output;
                        dc_predictor <= dc_predictor;
                    end
                endcase
            end
        endcase
    end

    //------------------------------------------------------------------------
    // Block 8: Output Assembly (Combinational)
    //------------------------------------------------------------------------
    always_comb begin
        decoded_symbol = 8'b0;
        symbol_valid = 1'b0;
        huffman_error = 1'b0;
        table_overflow = 1'b0;

        case (current_state)
            OUTPUT: begin
                case (select_dc_table)
                    1'b1: begin
                        decoded_symbol = dc_output[7:0];
                        symbol_valid = 1'b1;
                    end
                    1'b0: begin
                        case (decoded_sym)
                            8'h00: begin  // EOB
                                decoded_symbol = 8'h00;
                                symbol_valid = 1'b1;
                            end
                            8'hF0: begin  // ZRL
                                decoded_symbol = 8'hF0;
                                symbol_valid = 1'b1;
                            end
                            default: begin
                                decoded_symbol = {zero_run, value_bits};
                                symbol_valid = 1'b1;
                            end
                        endcase
                    end
                endcase
            end

            ERROR: begin
                huffman_error = 1'b1;
                symbol_valid = 1'b0;
            end

            default: begin
                huffman_error = 1'b0;
                symbol_valid = 1'b0;
            end
        endcase

        // Table overflow detection
        case (code_length == 4'b0)
            1'b1: table_overflow = 1'b1;
            default: table_overflow = 1'b0;
        endcase
    end

endmodule,"The provided code is a SystemVerilog module for a JPEG decoder. It includes several blocks of code that perform different tasks such as bitstream extraction, Huffman decoding, and output assembly among others.
